TP.register({id:"lp2-g8",lp:2,grade:"8",mode:"curriculum",checks:1,nextGrade:"high school",build(E){const F=E.F;const ico=(n,s=72)=>F.icon(n,s);const STORY_TITLE="One Clean Cut";const STORY=["The storm had split the old Harlow tree clean down the middle during the night, and by morning half of it lay in the grass like a dropped coat, its leaves still green and trembling.","“It comes down Friday,” said Mr. Teague, the orchard manager. He did not look up from his clipboard, where a long column of chores was already half crossed out. “A tree that can’t bear fruit is just a tall bill.”","Lucia had picked from that tree every fall since she was six, standing on an upturned crate until she was tall enough to reach the lowest branches. Its apples were small and lumpy, and they tasted like honey and lemon. No store sold them. No nursery did either.","“What if we graft it?” she said. “We could cut a few twigs from the living half and join them to a young tree. In time, the young tree would bear Harlow apples.”","“Grafting is tortoise work, Lucia, and you want a hare’s harvest. It would be four years before you saw one apple.”","“I’m thirteen,” she said. “I’ve got four years.”","Mr. Teague finally looked up. For a long moment he studied the broken tree, and then he studied her, as though weighing one against the other. “My grandfather planted that tree,” he said quietly. “I was hoping somebody would argue with me.”","He pulled a folding knife from his pocket and held it out, handle first. “One clean cut, on a slant. Don’t saw at it.”","Lucia’s hands were not steady, though the blade was sharp enough to forgive her. The twig came away with a pale green edge, bright as a struck match. She pressed it against a cut in the young tree and wrapped the two together, tight as a bandage, the way he showed her.","“Now what?” she asked.","“Now we wait.” Mr. Teague tore the top page off his clipboard, the one marked FRIDAY, folded it, and put it in his pocket."].join("\n\n");const story=()=>F.passage(STORY,STORY_TITLE,true);const SEED_TITLE="The Seed Gamble";const SEED=["If you plant a seed from your favorite apple, you will get an apple tree. You will almost certainly not get your favorite apple.","Each apple seed carries a new mix of traits from two parent trees: the tree that grew the fruit and the tree that supplied the pollen. A tree grown from seed is a genetic surprise. Its fruit is often small and sour, and it can take eight years or more to find that out.","Growers avoid the gamble by grafting. They cut a short twig, called a scion, from a tree whose fruit they like. They join it to the roots and trunk of a young tree, called the rootstock. The two heal together and grow as one tree. Every branch that grows from the scion makes the same fruit as the tree it came from. In other words, every tree of a named variety is a copy of one original tree.","The rootstock matters too. Some rootstocks keep a tree small. Small trees can be planted closer together, are easier to pick, and often bear fruit within three years.","Copying has a cost. Trees that are identical share the same weaknesses. A disease that can kill one tree of a variety can kill them all. For this reason, plant scientists keep collections of thousands of old and wild apple varieties. A gene from an almost forgotten tree may someday protect the apples sold in every store."].join("\n\n");const POEM_TITLE="Press Day";const POEM=[["The old press groans. The crank complains.","The apples go in whole and proud,","red-shouldered, loud with summer."],["They come out as a rope of gold","sliding slow into the pail."],["What is left is pulp, a pressed gray cake.","My aunt forks it over the garden wall.","“Nothing here is wasted,” she says.","“It only changes rooms.”"],["I drink. The cup is cold and sweet,","and summer is still in it."]];const poem=()=>`<h3 style="margin:0 0 4px;color:var(--sea);font-size:1.5rem">${POEM_TITLE}</h3><div class="poem" style="font-size:1.5rem;line-height:1.6;margin:0 0 16px">${POEM.map(s=>`<p style="margin:0 0 .7em">${s.join("<br>")}</p>`).join("")}</div>`;const fr=(a,b)=>`<sup>${a}</sup>⁄<sub>${b}</sub>`;const cards=a=>`<div class="figure" style="gap:14px">${a.map(x=>`<span style="display:inline-block;border:3px solid var(--line);border-radius:14px;background:var(--surface);padding:8px 20px;font-size:2rem;font-weight:700">${x}</span>`).join("")}</div>`;const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const factBox=(title,items)=>`<div style="border:3px dashed var(--line);border-radius:16px;background:var(--surface);padding:10px 20px;margin:14px 0"><p class="fig-label" style="margin:0 0 6px;text-align:left">${title}</p><ul style="margin:0;padding-left:1.2em;font-size:1.3rem;line-height:1.5">${items.map(x=>`<li>${x}</li>`).join("")}</ul></div>`;const srcCard=(tag,head,body)=>`<article style="flex:1 1 320px;border:2px solid var(--line);border-radius:16px;padding:12px 16px;background:var(--surface)"><h3 style="margin:0 0 4px;color:var(--sea)">${tag}</h3><p style="margin:0 0 8px;font-size:1.05rem;font-weight:700">${head}</p><p style="margin:0;font-size:1.3rem;line-height:1.5">${body}</p></article>`;const SOURCES=()=>`<p class="big" style="font-size:1.6rem">Research question: Do apple orchards need wild bees, or only honeybees?</p><div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px">${srcCard("Source 1","“Orchard Pollination Basics,” a fact sheet by Dr. Hana Sato. State University Farm Extension. Updated March 2025.","Apple blossoms need pollen from a different apple variety to make fruit. Honeybees do much of this work in large orchards. Wild bees matter too. Mason bees fly on cool, cloudy mornings when honeybees stay in the hive. Orchards with both kinds of bees are less likely to lose a crop to bad spring weather.")}${srcCard("Source 2","“BuzzMax Hive Rentals,” a web ad. No author. No date.","Wild bees are useless! Only BuzzMax honeybees can pollinate apples. Rent our hives and TRIPLE your harvest, guaranteed. Order today!")}</div>`;function grid(o){const S=o.size||500,max=o.max||8,u=(S-68)/(2*max),X=v=>34+(v+max)*u,Y=v=>S-34-(v+max)*u;const svg=F.coordGrid({max,quad4:true,size:S,labelEvery:1,polys:o.polys,points:(o.labels||[]).map(p=>[p[0],p[1]])});const t=(o.labels||[]).map(p=>`<text x="${X(p[0])+(p[3]||0)}" y="${Y(p[1])+(p[4]||0)}" font-size="17" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)" paint-order="stroke" stroke="var(--surface)" stroke-width="4">${p[2]}</text>`).join("");return svg.replace(/<\/svg>\s*$/,t+"</svg>")}const JKL=[[2,2],[6,2],[4,6]],JKL_L=[[2,2,"J",-14,-12],[6,2,"K",14,-12],[4,6,"L",0,-16]];const mapGrid=()=>grid({polys:[JKL],labels:JKL_L});const PQR=[[3,3],[6,3],[6,7]],PQR2=[[-3,3],[-3,6],[-7,6]];const mysteryGrid=()=>grid({polys:[PQR,PQR2],labels:[[3,3,"P",-14,-12],[6,3,"Q",14,-12],[6,7,"R",14,-10],[-3,3,"P′",14,12],[-3,6,"Q′",14,-12],[-7,6,"R′",-14,-12]]});const JKL2=[[-2,-6],[-6,-6],[-4,-2]];const twoMoveGrid=()=>grid({polys:[JKL,JKL2],labels:JKL_L.concat([[-2,-6,"J″",14,14],[-6,-6,"K″",-14,14],[-4,-2,"L″",0,-16]])});const bigTable=(head,rows)=>`<div class="tool-scroll"><table class="chart" style="margin:14px auto;font-size:1.4rem"><tr>${head.map(h=>`<th style="text-align:center">${h}</th>`).join("")}</tr>${rows.map(r=>`<tr>${r.map((c,i)=>i?`<td>${c}</td>`:`<th>${c}</th>`).join("")}</tr>`).join("")}</table></div>`;const DWARF=()=>`<div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px">${srcCard("Piece 1","“Replant the Blocks With Dwarfs”","A dwarf tree on modern rootstock bears fruit in its third year. A standard tree makes you wait eight. Dwarfs stay short enough to pick from the ground, so nobody carries a ladder, and you can fit four times as many of them on an acre. Over the first ten years an acre of dwarfs out-yields an acre of standards by a wide margin. Every modern orchard in the valley has replanted, so it must be the right call.")}${srcCard("Piece 2","“The Old Trees Earn Their Keep”","A dwarf block is not just trees. Dwarf rootstock cannot hold itself up, so it needs a trellis and drip irrigation from the first year, and that hardware is most of what a new block costs. A standard tree bears for sixty years. A dwarf block is pulled and replanted at about twenty. The ten year yield figure people quote stops counting at exactly the point where the standards are still going and the dwarfs are not.")}</div>`;const scatterFig=()=>F.coordGrid({max:10,size:340,xLabel:"age",yLabel:"bushels",points:[[2,3],[3,4],[4,5],[5,5],[6,7],[7,8],[8,9],[4,1]]});function ladderFig(){return`<svg viewBox="0 0 280 230" width="260" role="img" aria-label="A right triangle. The slanted side is a 13 foot ladder, the bottom is 5 feet from the trunk, and the upright side is the unknown height." style="max-width:100%;height:auto"><polygon points="40,190 40,40 190,190" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="3" stroke-linejoin="round"/><path d="M52 190 L52 178 L40 178" fill="none" stroke="var(--ink)" stroke-width="2"/><text x="115" y="214" font-size="18" font-weight="700" text-anchor="middle" fill="var(--ink)">5 ft</text><text x="128" y="106" font-size="18" font-weight="700" text-anchor="start" fill="var(--ink)">13 ft</text><text x="30" y="115" font-size="18" font-weight="700" text-anchor="end" fill="var(--ink)">?</text></svg>`}const STOPS=[{id:1,title:"One Clean Cut",short:"Cite It",parts:[{std:["RL.8.1"],dur:150,dir:"Read the story to yourself. Then answer out loud. Read me the exact words that prove each answer.",desc:"citing the strongest evidence for what a story says and for inferences",html:story,qs:["How long would it be before the grafted tree gave fruit? Read me the exact words that prove it.","Which one is stronger evidence that Harlow apples are rare? Pick A or B and tell why. A: “Its apples were small and lumpy.” B: “No store sold them. No nursery did either.”","Mr. Teague says the tree must come down. Does he really want to cut it down? Read me the one sentence that most strongly supports your answer.","The story never says what will happen on Friday. What do you think will happen? Read me the words that most strongly support your inference."],key:["Four years. Reads “It would be four years before you saw one apple.” (RL.8.1, explicit evidence)","B. It says nobody sells the apples or the trees, so they are hard to get. A only tells what the apples look like. (RL.8.1, strongest evidence)","No, he does not want to. Strongest evidence: “I was hoping somebody would argue with me.” A weaker choice is “My grandfather planted that tree.” Full credit for the first sentence. (RL.8.1, strongest evidence for an inference)","The tree will not be cut down on Friday, at least for now. Strongest evidence: he “tore the top page off his clipboard, the one marked FRIDAY, folded it, and put it in his pocket.” May add “Now we wait.” (RL.8.1, inference)"]}]},{id:2,title:"The Sorting Line",short:"Sort It",parts:[{std:["8.NS.A.1"],dur:180,dir:"The orchard sorts apples. You sort numbers. Answer out loud. Use your paper for the division.",desc:"sorting rational and irrational numbers and showing that fractions have repeating decimals",html:()=>cards(["0.6","√49","√11","−"+fr(5,8),"0.272727...","2π"]),qs:["Sort the six number cards into two bins: rational and irrational. Tell how you decided.","√49 has a root sign. Why is it still a rational number?","Divide to write "+fr(5,6)+" as a decimal. Which digit repeats?","Divide to write "+fr(3,11)+" as a decimal. Which number card does it match?","Find the error. A picker says, “0.1666... goes on forever, so it must be irrational.” What is wrong with that?","Name one irrational number that is between 3 and 4."],key:["Rational: 0.6, √49, −5/8, 0.272727... Irrational: √11 and 2π. Reason: a rational number can be written as a fraction of two integers, and its decimal ends or repeats. An irrational decimal never ends and never repeats. Partial: the six sorted right with no reason is approaching, and so is one misplaced card with the reasoning sound. (8.NS.A.1)","√49 = 7, and 7 can be written as 7/1. (8.NS.A.1)","0.8333... The 3 repeats. Long division: 50 ÷ 6 = 8 with 2 left over, then 20 ÷ 6 = 3 with 2 left over, again and again. Or: 5/6 as 5 × 1/6, and 1/6 is 0.1666... Partial: the decimal right with no repeating digit named is approaching. (8.NS.A.1)","0.272727... The digits 27 repeat. It matches the card 0.272727... Or: 3/11 as 3 × 1/11, and 1/11 is 0.0909... (8.NS.A.1)","A decimal that goes on forever can still be rational when it repeats. 0.1666... repeats the 6, and it equals 1/6. Irrational decimals never end and never repeat. Partial: saying it is rational with no account of the repeating block is approaching. (8.NS.A.1)","Any one of √10, √11, √12, √13, √14, √15, or π. Check: 3² = 9 and 4² = 16, so the root of any whole number from 10 to 15 is between 3 and 4. Or: build a non-repeating decimal of your own, such as 3.10100100..., which also counts. (8.NS.A.1)"]}]},{id:3,title:"Orchard Map Moves",short:"Map Moves",parts:[{std:["8.G.A.3"],dur:210,dir:"Triangle JKL is a block of young trees on the orchard map. Start from the original triangle each time. Tell your teacher the new coordinates.",desc:"coordinates after a translation, a reflection, rotations, and a dilation",fig:()=>`<div class="figure">${mapGrid()}</div>`,qs:["Translate triangle JKL 7 units left and 3 units down. What are the new coordinates of J, K, and L?","Reflect triangle JKL across the x-axis. What are the new coordinates? Which coordinate changed, x or y?","Rotate triangle JKL 180° about the origin. What are the new coordinates?","Dilate triangle JKL by a scale factor of "+fr(1,2)+" from the origin. What are the new coordinates? What happens to the length of side JK?","Rotate triangle JKL 90° clockwise about the origin. Where does point K land?"],key:["J′(−5, −1), K′(−1, −1), L′(−3, 3). Subtract 7 from each x and subtract 3 from each y. Or: count the squares on the grid instead of using the rule. Partial: two of the three points right is approaching. (8.G.A.3)","J′(2, −2), K′(6, −2), L′(4, −6). The y-coordinates change sign. The x-coordinates stay the same. Partial: the three points right with the wrong coordinate named is approaching. (8.G.A.3)","J′(−2, −2), K′(−6, −2), L′(−4, −6). Both coordinates change sign: (x, y) → (−x, −y). Or: two reflections, one across each axis, give the same result as the half turn. (8.G.A.3)","J′(1, 1), K′(3, 1), L′(2, 3). Multiply every coordinate by 1/2. Side JK goes from 4 units to 2 units, half as long. Partial: the three points right with nothing said about side JK is approaching. (8.G.A.3)","K′(2, −6). The rule is (x, y) → (y, −x). Whole triangle: J′(2, −2), L′(6, −4). Or: trace the triangle and turn the paper a quarter turn, or call it a 270° counterclockwise turn. Partial: K′ right with no rule named is approaching. (8.G.A.3)"]}]},{id:4,title:"Talk That Turns",short:"Dialogue",parts:[{std:["RL.8.3"],dur:130,dir:"Read the story to yourself. Then answer out loud. Read me the line you are talking about.",desc:"explaining how lines of dialogue and events provoke a decision, reveal character, and move a story forward",html:story,qs:["Which line of Lucia’s dialogue changes Mr. Teague’s mind? Read it. Then explain how it leads to what he does next.","Mr. Teague says, “I was hoping somebody would argue with me.” What does this line reveal about him?","The storm splits the tree before the story begins. How does that one event set everything else in motion?","Mr. Teague holds out the knife “handle first” and lets Lucia make the cut. What does this action show about his decision and about how he sees her?"],key:["“I’m thirteen. I’ve got four years.” It answers his point that grafting is too slow. Right after it he finally looks up, admits he hoped someone would argue, and hands her the knife. Give partial credit for “What if we graft it?” with a clear explanation. (RL.8.3, dialogue provokes a decision)","He did not really want to cut the tree down. He cares about it because his grandfather planted it, but he was hiding that behind business talk. (RL.8.3, dialogue reveals character)","The broken tree cannot bear fruit, so Mr. Teague plans to cut it down on Friday. That deadline pushes Lucia to speak up and suggest grafting. Without the storm there is no problem to solve. (RL.8.3, an incident propels the action)","He has decided to try the graft, and he trusts Lucia to do the important part herself. He treats her as a partner, not a little kid. (RL.8.3, an incident reveals character and a decision)"]}]},{id:5,title:"Loaded Words",short:"Word Choice",parts:[{std:["RL.8.4"],dur:135,dir:"Read the story to yourself. Then answer out loud.",desc:"figurative language, connotation and tone, and an allusion in a story",html:story,qs:["The broken half of the tree “lay in the grass like a dropped coat.” What does this comparison help you picture? What feeling does it create?","Mr. Teague calls the tree “just a tall bill.” The tree is not really a bill. What does he mean? What does this word choice tell you about his tone at the start?","Mr. Teague says, “Grafting is tortoise work, Lucia, and you want a hare’s harvest.” In an old fable, a slow, steady tortoise wins a race against a fast hare. What is he saying about grafting and about Lucia?","The cut twig is “bright as a struck match.” Why do you think the author chose a struck match and not just the words “bright green”? How does the mood of the story change here?"],key:["The half tree looks limp and tossed aside, like something left behind. It creates a sad feeling of loss, or of something once cared for now thrown away. (RL.8.4, figurative meaning)","He means the tree only costs money now and earns nothing. The tone is cold, practical, and businesslike. (RL.8.4, figurative meaning and tone)","Grafting is slow, patient work, and he thinks Lucia wants a fast result. A strong answer may add that the tortoise wins in the end, which hints that slow work pays off. (RL.8.4, allusion)","A struck match is a small spark that starts a fire. It suggests a new start, life, and hope. The mood turns from sad or tense to hopeful. (RL.8.4, connotation and tone)"]}]},{id:6,title:"The Seed Gamble",short:"Seed Gamble",parts:[{std:["RI.8.1"],dur:150,dir:"Read the article to yourself. Then answer out loud. Read me the exact words that prove each answer.",desc:"citing the strongest evidence from a science article for explicit answers and inferences",html:()=>F.passage(SEED,SEED_TITLE,true),qs:["What happens if you plant a seed from your favorite apple? Read me the exact words that prove it.","The author calls a tree grown from seed “a genetic surprise.” Which sentence most strongly explains why? Read it to me.","Claim: Grafting can save a grower years of waiting. Find the two details that, together, most strongly support this claim.","A farmer plants 500 trees of one variety. A new disease can kill one of those trees. Is the rest of the orchard safe? Read me the words that most strongly support your inference."],key:["You get an apple tree, but almost never the same kind of apple. Reads “You will almost certainly not get your favorite apple.” (RI.8.1, explicit evidence)","“Each apple seed carries a new mix of traits from two parent trees: the tree that grew the fruit and the tree that supplied the pollen.” (RI.8.1, strongest evidence)","A tree from seed “can take eight years or more,” and small grafted trees “often bear fruit within three years.” Both details are needed, because the claim compares the two. (RI.8.1, strongest evidence)","No. Strongest evidence: “A disease that can kill one tree of a variety can kill them all.” Also accept “Trees that are identical share the same weaknesses.” (RI.8.1, inference)"]}]},{id:7,title:"Decimals on Repeat",short:"Repeats",parts:[{std:["8.NS.A.1"],dur:210,dir:"The cider scale prints repeating decimals. Turn each one into a fraction. Show your steps on your paper and hold it up.",desc:"converting repeating decimals to fractions",qs:["0.555... (the 5 repeats)","0.363636... (the 36 repeats)","1.222... (the 2 repeats)","0.2444... (only the 4 repeats)","Find the error. Dev wrote: x = 0.5454..., so 10x = 5.4545..., so 9x = 5 and x = "+fr(5,9)+". What went wrong? What is the correct fraction?"],key:["5/9. Steps: x = 0.555..., 10x = 5.555..., subtract to get 9x = 5, so x = 5/9. Or: name it from the pattern, since 0.111... is 1/9 so 0.555... is 5/9. Partial: 5/9 with no steps shown is approaching. (8.NS.A.1)","36/99 = 4/11. Steps: two digits repeat, so multiply by 100. 100x = 36.3636..., subtract x to get 99x = 36, so x = 36/99 = 4/11. Accept 36/99. Or: name it from the pattern, since a two-digit repeat sits over 99. Partial: 36/99 not reduced still counts; the method is what is rated. (8.NS.A.1)","11/9, or 1 and 2/9. Steps: 10x = 12.222..., subtract x = 1.222... to get 9x = 11, so x = 11/9. Or: split off the whole number first, 1 + 0.222..., and 0.222... is 2/9. (8.NS.A.1)","22/90 = 11/45. Steps: 10x = 2.444... and 100x = 24.444..., subtract to get 90x = 22, so x = 22/90 = 11/45. Accept 22/90. (8.NS.A.1)","Two digits repeat, so Dev had to multiply by 100, not 10. With 10x the repeating parts do not line up, and 5.4545... minus 0.5454... is not 5. Correct: 100x = 54.5454..., 99x = 54, x = 54/99 = 6/11. Partial: the right fraction with no account of what Dev did is approaching. (8.NS.A.1)"]}]},{id:8,title:"Mystery Moves",short:"Mystery Moves",parts:[{std:["8.G.A.3"],dur:180,dir:"Someone moved things on the orchard map. Answer out loud. Use the grid for number 3.",desc:"describing transformations from coordinates and finding an error in a reflection",qs:["The well is at W(3, −4). Reflect it across the y-axis. Where does it land?","A gate moves from (−2, 5) to (4, 1). Describe the translation in words.","Look at the grid. Triangle PQR was moved onto triangle P′Q′R′ with one transformation. Which transformation was it? What happens to each (x, y)?","Find the error. Mara reflected the point (5, −2) across the x-axis and wrote (−5, −2). What did she do wrong? What is the correct point?","A square plot has one corner at (2, −1), and its sides are 4 units long. The plot is dilated by a scale factor of 3 from the origin. Where does that corner land? How long is each side now?"],fig2:()=>`<div class="figure">${mysteryGrid()}</div>`,key:["(−3, −4). The x-coordinate changes sign and the y-coordinate stays the same. Partial: the point right with no account of which coordinate changes is approaching. (8.G.A.3)","6 units right and 4 units down. As a rule: (x, y) → (x + 6, y − 4). Partial: the words right with no rule, or the rule with no words, is approaching. (8.G.A.3)","A rotation of 90° counterclockwise about the origin. Rule: (x, y) → (−y, x). Check: P(3, 3) → P′(−3, 3), Q(6, 3) → Q′(−3, 6), R(6, 7) → R′(−7, 6). Also accept 270° clockwise. (8.G.A.3)","She changed the sign of x, which is a reflection across the y-axis. Across the x-axis the y-coordinate changes sign, so the correct point is (5, 2). Partial: the right point, (5, 2), with no account of Mara's mistake is approaching. (8.G.A.3)","The corner lands at (6, −3). Each side is 12 units long, 3 times as long. Partial: the corner right with nothing said about the side length is approaching. (8.G.A.3)"]}]},{id:9,title:"Grammar Graft",short:"Grammar",parts:[{std:["L.8.1"],dur:130,dir:"Answer out loud. For numbers 4 and 6, say the whole sentence the correct way.",desc:"verbals, active and passive voice, and verb moods",qs:["“Pruning keeps an apple tree healthy.” Which word is the verbal? What kind is it, and what job does it do in the sentence?","“The fallen apples attracted wasps.” Find the verbal and name its kind. What does it describe?","“The crew hopes to finish the last row by noon.” Find the verbal and name its kind.","Change this sentence to active voice: “The cider was pressed by the volunteers on Saturday.”","“Close the gate behind you.” Does this sentence state a fact, ask a question, or give a command? Name the mood.","Fix the verb: “If the orchard was mine, I would plant fifty more trees.”"],key:["Pruning. Gerund. It is the subject of the sentence, so it acts as a noun. (L.8.1, verbals)","fallen. Participle. It describes apples, so it acts as an adjective. (L.8.1, verbals)","to finish. Infinitive. (L.8.1, verbals)","The volunteers pressed the cider on Saturday. (L.8.1, active and passive voice)","It gives a command. Imperative mood. (L.8.1, verb moods)","If the orchard were mine, I would plant fifty more trees. The orchard is not really mine, so the verb is were. (L.8.1, subjunctive mood)"]}]},{id:10,title:"Press Day",short:"Press Day",parts:[{std:["RL.8.4"],dur:100,dir:"Read the poem to yourself. Then answer out loud.",desc:"figurative language, connotation, and tone in a poem",html:poem,qs:["“The old press groans. The crank complains.” A machine cannot really complain. What do these words tell you about the press?","The cider comes out as “a rope of gold.” What is the poet describing? What does the word gold suggest that “brown juice” would not?","The aunt says the apples are not wasted. “It only changes rooms.” What does she mean? What is being compared?","Choose the word that best fits the tone at the end of the poem: thankful, angry, or nervous. Which words in the poem made you choose it?"],key:["The press is old, heavy, and hard to turn, and it makes creaking noises as it works. The poet gives it human actions. (RL.8.4, figurative meaning)","The thick stream of cider pouring into the pail. Gold suggests something valuable, beautiful, and worth keeping. (RL.8.4, figurative and connotative meaning)","Nothing is really gone. The apples only change form: the juice becomes cider and the pulp goes to feed the garden. She compares changing form to moving from one room of a house to another. (RL.8.4, analogy)","Thankful. Also accept calm or content. Evidence such as “cold and sweet,” “summer is still in it,” or “Nothing here is wasted.” (RL.8.4, word choice and tone)"]}]},{id:11,title:"Source Check",short:"Sources",parts:[{std:["W.8.8"],n:5,label:"checks met",dur:180,dir:"Read both sources. Answer numbers 1 and 2 out loud. Do numbers 3, 4, and 5 on your paper and hold it up.",desc:"research skills (judging sources, paraphrasing, quoting, and citing)",html:()=>SOURCES()+`<ol class="qlist"><li>Which source would you trust more for a school report? Give two reasons.</li><li>Source 2 says, “Wild bees are useless!” How could you check whether that is accurate?</li><li>Paraphrase one fact from Source 1. Use your own words.</li><li>Copy one sentence from Source 1 as a direct quote. Use quotation marks and name the author.</li><li>Write a citation for Source 1 with the author, title, publisher, and date.</li></ol>`,key:["Source 1. Two reasons, such as: it names an expert author, it comes from a university, it has a date, it explains instead of selling. Source 2 is an ad with no author and no date, and the company makes money if you believe it. (W.8.8, credibility)","Compare it with other reliable sources. Source 1 says “Wild bees matter too,” so the two sources disagree. Look for a third source from a university or science group. (W.8.8, accuracy)","A correct fact from Source 1 in the student’s own words, not copied. Example: Mason bees keep working in cool, cloudy weather when honeybees do not. (W.8.8, paraphrase)","One exact sentence from Source 1 inside quotation marks, with Dr. Hana Sato named. Example: Dr. Hana Sato writes, “Wild bees matter too.” (W.8.8, quoting without plagiarism)","Has all four parts. Example: Sato, Hana. “Orchard Pollination Basics.” State University Farm Extension, March 2025. Any clear, consistent order is fine. (W.8.8, citation)"]}]},{id:12,title:"Pitch the Plan",short:"Pitch It",parts:[{std:["SL.8.4"],n:5,label:"checks met",dur:120,dir:"Plan for 1 minute. Then talk for 45 to 60 seconds. Look at the camera and speak clearly.",desc:"a 45 to 60 second spoken claim with evidence and reasoning",html:()=>`<p class="big">The orchard has 400 pounds of bruised apples. Which plan is better? Make your claim and defend it with facts from the chart.</p>${bigTable(["","Plan A: Bargain bin","Plan B: Press cider"],[["Money earned","about $200","about $270"],["Work","about 1 hour","about 4 hours"],["Extra needs","none","30 jugs and a clean press"],["How long it keeps","apples sell within 1 week","cider keeps about 10 days in the cooler"]])}${checklist(["Say your claim first","Give at least two facts from the chart","Explain how the facts prove your claim","End by saying your claim again"])}`,key:["States a clear claim (Plan A or Plan B) at the start. Either plan can earn full credit. (SL.8.4)","Stays focused and puts the main points in an order that makes sense. (SL.8.4)","Uses at least two relevant facts from the chart, such as $270 compared with $200, or 1 hour compared with 4 hours. (SL.8.4)","Gives sound reasoning that connects the facts to the claim, such as: Plan B earns $70 more but takes 3 more hours of work. (SL.8.4)","Looks at the camera, speaks loudly enough, and pronounces words clearly. Talks for about 45 to 60 seconds. (SL.8.4)"]}]},{id:13,title:"Orchard Writer",short:"Write",parts:[{alt:{group:"write",key:"informative",label:"Explain",icon:"📰",hint:"How can apples stay crisp until spring?"},std:["W.8.2"],n:6,label:"checks met",dur:300,dir:"Write on your paper for 5 minutes. Then hold it up or read it to your teacher.",desc:"an informative writing piece built from a fact box",html:()=>`<p class="big">Apples are picked in the fall, but stores sell crisp apples in the spring. Write to explain how that is possible. Use the fact box. Write 6 to 8 sentences.</p>${factBox("Fact box: cold storage",["Apples are picked in September and October.","A picked apple is still alive. It takes in oxygen and slowly ripens.","Storage rooms are cooled to just above freezing.","The rooms are sealed, and the oxygen in the air is lowered from 21% to about 2%.","With so little oxygen, apples ripen very slowly. Some kinds stay crisp for 10 months.","This is called controlled atmosphere storage."])}${checklist(["Introduce the topic","Put the facts in an order that makes sense","Explain the facts in your own sentences","Use linking words: because, as a result, for example","Use topic words: oxygen, ripen, controlled atmosphere","End with a conclusion"])}`,key:["Introduces the topic clearly and lets the reader know what is coming (W.8.2)","Organizes the ideas in a logical order, such as picking, cooling, sealing, and the result (W.8.2)","Develops the topic with relevant facts, a definition, and details from the fact box, such as oxygen lowered from 21% to about 2% (W.8.2)","Uses transitions to connect ideas, such as because, as a result, for example (W.8.2)","Uses precise language and topic words, such as oxygen, ripen, controlled atmosphere, and keeps a formal style (W.8.2)","Ends with a concluding statement that follows from the explanation (W.8.2)"]},{alt:{group:"write",key:"narrative",label:"Story",icon:"📖",hint:"Last bin, last hour, and the tractor will not start"},std:["W.8.3"],n:6,label:"checks met",dur:300,dir:"Write on your paper for 5 minutes. Then hold it up or read it to your teacher.",desc:"a narrative writing piece",html:()=>`<p class="big">It is the last hour of the last day of harvest. One full bin of apples is still out in the far row, and the tractor will not start. Write the story of what happens. It can be real or made up. Write 6 to 8 sentences.</p>${checklist(["Set the scene: who is there, and who is telling the story","Tell what happens in order","Include at least one line of dialogue","Use details the reader can see, hear, or feel","Use time words: at first, meanwhile, by the time, finally","End by showing what the narrator learned or felt"])}`,key:["Sets up the situation and point of view and introduces the narrator or characters (W.8.3)","Events unfold in an order that is natural and logical (W.8.3)","Uses narrative techniques such as dialogue, pacing, description, or reflection (W.8.3)","Uses transition words to show sequence and shifts in time or place (W.8.3)","Uses precise words, descriptive details, and sensory language (W.8.3)","Ends with a conclusion that follows from and reflects on the events (W.8.3)"]}]},{id:14,title:"Dwarfs or Standards",short:"Two Cases",parts:[{std:["RI.8.8","RI.8.9"],n:3,dur:60,dir:"Read both pieces. Answer out loud.",desc:"evaluating an argument and its evidence, and analyzing where two texts conflict",html:()=>DWARF(),qs:["Delineate the argument in Piece 1. What is the claim, and what evidence is given for it?","One sentence in Piece 1 is not evidence at all. Which one, and why does it not count?","The two pieces disagree about the same ten year figure. What does Piece 2 say is wrong with it, and what would you need in order to decide between them?"],key:["Claim: the orchard should replant its blocks with dwarf trees. Evidence: dwarfs bear in year three against eight for standards, they can be picked from the ground, four times as many fit on an acre, and an acre of dwarfs out-yields an acre of standards over ten years (RI.8.8, delineates the argument)","Every modern orchard in the valley has replanted, so it must be the right call. That is what other people are doing, not a reason it pays. It is irrelevant to whether dwarfs earn more on this orchard (RI.8.8, irrelevant evidence)","Piece 2 says the ten year window is chosen to flatter the dwarfs: it stops right where the standards keep bearing and the dwarf block has to be pulled and replanted at about twenty years. To decide, you would need yield and cost over the full life of each block, including the trellis and irrigation, not a ten year slice (RI.8.9, conflicting information)","A student who only says they disagree has not met this. The answer has to name the point of conflict and what evidence would settle it."]}]},{id:15,title:"Make the Case",short:"Argue",parts:[{std:["W.8.1"],n:4,label:"checks met",dur:45,dir:"Write a short answer on your paper. Then hold it up or read it to your teacher.",desc:"a short written argument with a claim, evidence, and an acknowledged counterclaim",html:()=>`<p class="big">Should the orchard replant with dwarf trees or keep the standards? Write your claim, one piece of evidence for it, and one sentence that admits the strongest point on the other side. Write 3 or 4 sentences.</p>${DWARF()}${checklist(["Claim first, in one sentence","One piece of evidence from the pieces, in your own words","One sentence naming the other side's strongest point","One sentence saying why your claim still holds"])}`,key:["Introduces a clear claim about which way to go (W.8.1)","Supports it with relevant evidence drawn from the two pieces (W.8.1)","Acknowledges the opposing claim fairly rather than mocking it (W.8.1)","Keeps a formal style and ends with a sentence that follows from the argument (W.8.1)","Either side is defensible. Rate the claim, the evidence and the counterclaim, not the side."]}]},{id:16,title:"Powers and Roots",short:"Powers",parts:[{std:["8.EE.A.1","8.EE.A.2"],n:3,dur:60,dir:"Answer out loud. Show your work on your paper.",desc:"using integer exponent rules, and solving with square and cube roots",html:()=>cards(["3² × 3⁴","5⁻²","x² = 49"]),qs:["Write 3² × 3⁴ as a single power, then give its value.","What is 5⁻²? Say it as a fraction.","Solve x² = 49. Then give the cube root of 64, and say whether √2 is rational or irrational."],key:["3⁶, which is 729. The exponents add because the bases are the same. Or: write out six 3s and multiply. Partial: 3⁶ right with the value wrong is approaching. (8.EE.A.1)","1/25. A negative exponent means one over the power, not a negative number. Or: 5⁻² as 5⁰ ÷ 5² = 1 ÷ 25. Partial: −25 or −10 shows the negative exponent read as a negative number and does not count. (8.EE.A.1)","x = 7 or x = -7. Both roots are needed. The cube root of 64 is 4. √2 is irrational: 2 is not a perfect square, so its decimal never ends and never repeats. Partial: two of the three parts right is approaching, and x = 7 alone leaves the negative root out. (8.EE.A.2)"]}]},{id:17,title:"Two Presses",short:"Slope",parts:[{std:["8.EE.B.5"],n:3,dur:45,dir:"Look at the table. Answer out loud.",desc:"interpreting unit rate as slope and comparing two proportional relationships",fig:()=>bigTable(["Press B: bushels","2","4","6"],[["Gallons of cider","7","14","21"]]),html:()=>`<p class="big" style="text-align:center">Press A follows g = 3b, where b is bushels and g is gallons.</p>`,qs:["What is the unit rate for Press B? How did you get it?","If both were graphed with bushels across the bottom, which line would be steeper?","What does the slope stand for here?"],key:["3.5 gallons a bushel. 7 ÷ 2, and the same ratio holds at 14 ÷ 4 and 21 ÷ 6. Or: read the rise over the run off the graph. Partial: 3.5 with no account of how it was found is approaching. (8.EE.B.5)","Press B. Its slope is 3.5 against the 3 in g = 3b. Or: compare the two graphs side by side instead of the two numbers. Partial: the right press with no rates compared is approaching. (8.EE.B.5)","Gallons of cider got out of each bushel of apples. Both lines pass through the origin, because no apples gives no cider (8.EE.B.5)"]}]},{id:18,title:"Same Price",short:"System",parts:[{std:["8.EE.C.8"],n:3,dur:45,dir:"Write the system on your paper and solve it. Say your answers out loud.",desc:"writing and solving a system of two linear equations and saying what the solution means",html:()=>`<p class="big" style="text-align:center">Stand A charges $6 to get in and $4 a bag.<br>Stand B charges nothing to get in and $7 a bag.</p>`,qs:["Write an equation for the cost at each stand, using b for bags.","Solve the system. How many bags makes the two costs equal?","What does your solution mean for a customer buying 5 bags?"],key:["Stand A: c = 4b + 6. Stand B: c = 7b. Partial: one of the two equations right is approaching. (8.EE.C.8)","2 bags, and the cost is $14 at both. 4b + 6 = 7b gives 3b = 6 and b = 2. Or: graph both lines and read the crossing point, or make a table and look for the row where the costs match. Partial: b = 2 with no cost given is approaching. (8.EE.C.8)","Past 2 bags, Stand A is cheaper. At 5 bags, Stand A is 4(5) + 6 = $26 and Stand B is 7(5) = $35, so Stand A saves $9. Partial: naming Stand A with no numbers for 5 bags is approaching. (8.EE.C.8)","The solution is the point where the two lines cross. A student who finds b = 2 but cannot say what it means has only done the algebra."]}]},{id:19,title:"Is It a Function",short:"Functions",parts:[{std:["8.F.A.1","8.F.A.3"],n:3,dur:60,dir:"Look at the table. Answer out loud.",desc:"deciding whether a relation is a function and whether a rule is linear",fig:()=>bigTable(["Bushels in","3","5","5","8"],[["Gallons out","10","17","14","26"]]),qs:["The table records one day at the press. Is this a function of bushels in? Say why.","Press A follows g = 3b. Is that a linear function? What are its rate of change and its starting value?","Is y = 2x² + 1 a linear function? Say why or why not."],key:["No. The input 5 appears twice with two different outputs, 17 and 14. A function gives exactly one output for each input, so this day's record is not one. Partial: no with no account of the repeated input is approaching. (8.F.A.1)","Yes. It is in the form y = mx + b with m = 3 and b = 0, so the rate of change is 3 gallons a bushel and it starts at 0. Partial: yes with one of the rate and the starting value missing is approaching. (8.F.A.3)","No. The x is squared, so equal steps in x do not give equal steps in y: at x = 1, 2, 3 the values are 3, 9, 19. A linear function has a constant rate of change. Or: sketch it and show the graph curves. Partial: no with no reason is approaching. (8.F.A.3)"]}]},{id:20,title:"Ladder and Bin",short:"Pythagoras",parts:[{std:["8.G.B.7"],n:3,dur:45,dir:"Solve on your paper. Say your answers out loud.",desc:"using the Pythagorean theorem to find an unknown length in two and three dimensions",fig:()=>`<div class="figure">${ladderFig()}</div>`,qs:["A 13 foot ladder leans against the trunk with its feet 5 feet out. How high up the trunk does it reach?","A bin floor is 6 feet by 8 feet. How long is the diagonal across the floor?","Could a straight 11 foot pole lie flat on that bin floor? Say why."],key:["12 feet. 5² + h² = 13², so h² = 169 - 25 = 144 and h = 12. Or: recognize the 5, 12, 13 triple. Partial: 144 found with no square root taken is approaching. (8.G.B.7)","10 feet. 6² + 8² = 36 + 64 = 100, so the diagonal is 10. Or: recognize the 6, 8, 10 triple. Partial: 14 feet from adding the two sides does not count. (8.G.B.7)","No. The longest straight line that fits flat on the floor is the 10 foot diagonal, and 11 is longer than that. Partial: no with no comparison to the 10 foot diagonal is approaching. (8.G.B.7)"]}]},{id:21,title:"Age and Yield",short:"Scatter",parts:[{std:["8.SP.A.1"],n:3,dur:45,dir:"Look at the scatter plot. Each dot is one tree. Answer out loud.",desc:"describing association, form, and an outlier in a scatter plot of two measurements",fig:()=>`<div class="figure">${scatterFig()}</div>`,qs:["Describe the association between a tree's age and the bushels it gave.","Is the pattern roughly linear, or is it curved?","One dot does not fit the pattern. Which one, and what might explain it?"],key:["A positive association: as age goes up, bushels go up. Older trees in this sample gave more. Partial: positive named with no account of what goes up with what is approaching. (8.SP.A.1)","Roughly linear. The dots that follow the pattern sit near a straight line (8.SP.A.1)","The 4 year old tree that gave only 1 bushel. It sits well below every other dot. Something about that one tree, such as damage, disease or a bad graft, would explain it better than its age does. Partial: the dot named with no possible reason is approaching. (8.SP.A.1)","Saying there is no pattern because of the one odd dot is the answer to watch for. An outlier does not erase the association."]}]},{id:22,title:"Older Roots",short:"Roots",parts:[{std:["HSS-8.1"],n:3,dur:95,dir:"Look at the chart. Answer out loud.",desc:"tracing the English and colonial roots of American constitutional democracy",html:()=>`<p class="big">The orchard's reading room keeps a chart of where American self government came from. None of these documents was written in America.</p>
     <table class="bigTable"><tr><th>Year</th><th>Document or practice</th><th>What it established</th></tr>
     <tr><td>1215</td><td>Magna Carta</td><td>the king is under the law, and a free man may not be jailed without lawful judgment</td></tr>
     <tr><td>1619</td><td>Virginia House of Burgesses</td><td>the first elected lawmaking body in the colonies</td></tr>
     <tr><td>1620</td><td>Mayflower Compact</td><td>settlers agreed in writing to govern themselves by laws they made together</td></tr>
     <tr><td>1689</td><td>English Bill of Rights</td><td>no taxes or standing army without Parliament's consent, and a right to petition</td></tr>
     <tr><td>1600s to 1700s</td><td>New England town meetings</td><td>residents voted in person on local spending and local rules</td></tr></table>
     <div class="figure">${ico("books",74)}${ico("tree",74)}${ico("hands",74)}</div>`,qs:["Which row do you think colonists leaned on most when they objected to the Stamp Act, and why?","By 1765 the colonies had been electing their own assemblies for well over a century. Why did that make Parliament's new taxes feel like a change rather than normal government?","Pick two rows and name a part of the United States Constitution or the Bill of Rights that grew out of each."],key:["The 1689 English Bill of Rights, because it already held that taxes required the consent of the people's representatives. Accept Magna Carta with a reason, since it established that even a king is bound by law. A strong answer names the row and explains the link rather than only picking one. Partial: picking a row with no link explained is approaching. (HSS-8.1)","A hundred and fifty years of electing assemblies and voting at town meetings made local self government the ordinary way things worked, so colonists did not see themselves as asking for something new. A tax voted by a body they had never elected looked like their own assemblies being pushed aside. Partial: naming the long habit of self government with nothing said about how the tax looked to them is approaching. (HSS-8.1)","Any two with a real link. Magna Carta to due process and the ban on jailing without lawful judgment. The English Bill of Rights to the taxing power resting with Congress, to the right to petition, and to the limits on a standing army. The House of Burgesses and town meetings to an elected legislature and to the idea that the people are the source of a government's authority. Partial: one pair linked correctly is approaching, and two rows named with no link is approaching too. (HSS-8.1)"]},{std:["HSS-8.2"],n:3,dur:100,dir:"Look at the chart. Answer out loud.",desc:"assigning actions to branches and sorting enumerated from implied powers",html:()=>`<p class="big">Four things the national government has done.</p>
     <table class="bigTable"><tr><th></th><th>Action</th></tr>
     <tr><td>A</td><td>Congress votes to declare war</td></tr>
     <tr><td>B</td><td>Congress creates an air traffic control system and a federal agency to run it</td></tr>
     <tr><td>C</td><td>The Supreme Court strikes down an act of Congress as unconstitutional</td></tr>
     <tr><td>D</td><td>Congress sets up post offices and post roads</td></tr></table>
     <div class="figure">${ico("flag",74)}${ico("books",74)}${ico("truck",74)}</div>`,qs:["Which of these four are enumerated powers, written out in the Constitution, and which is an implied power? Explain the one that is implied.","Action C is not listed anywhere in the Constitution either. Where does that power come from, and what is it called?","Why would the framers include a clause that lets Congress reach beyond the written list at all?"],key:["A and D are enumerated: declaring war and establishing post offices and post roads are both in the list of congressional powers. B is implied: aircraft did not exist in 1787, so Congress reaches it through the power to regulate commerce among the states plus the necessary and proper clause, since air travel crosses state lines and needs one set of rules. Partial: two of the three sorted right is approaching. (HSS-8.2)","From the Court's own reading of the Constitution, established in Marbury v. Madison in 1803. It is called judicial review. It is a check on the other two branches that the document does not spell out. Partial: naming judicial review with nothing said about where it came from is approaching. (HSS-8.2)","Because no list written in 1787 could name every situation a government would face, and a government that could act only on an exact list would be helpless the first time something new appeared. The clause lets Congress choose the means of carrying out powers it already has, which is also why arguments about how far it stretches have never stopped. Partial: naming the clause with nothing said about why a fixed list would not do is approaching. (HSS-8.2)"]},{std:["HSS-8.3"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"explaining how political parties formed and how citizens take part through them",html:()=>`<p class="big">The Constitution says nothing about political parties. They appeared anyway. By 1796 one group around Alexander Hamilton wanted a strong national government, a national bank and close trade with Britain, and another around Thomas Jefferson wanted power left with the states, an economy of farmers, and sympathy for France. Each ran newspapers, each organized voters state by state, and each called the other a danger to the republic.</p>
     <div class="figure">${ico("flag",74)}${ico("radio",74)}${ico("hands",74)}</div>`,qs:["Name two things a political party does that a single candidate cannot do alone.","Parties were not planned and several founders disliked them. Why did they form anyway?","A voter today takes part in two elections for the same office. What is the difference between them, and which one does a party control?"],key:["Any two: it recruits and nominates candidates for many offices at once, it states a program so voters know roughly what a candidate stands for, it organizes volunteers and money across a whole state or country, it gets voters registered and to the polls, and it holds its officeholders to a shared position once they are in. Partial: one job of a party named is approaching. (HSS-8.3)","Because people who agreed on the big questions found it far more effective to act together than separately: a bloc could win elections, control a legislature and carry a program through. Once one side organized, the other had to. Parties became the practical machinery of participation in a system the Constitution left open on this point. Partial: noting that parties appeared with no account of why organizing worked better is approaching. (HSS-8.3)","A primary, where the members or supporters of one party choose that party's nominee, and the general election, where voters choose among the parties' nominees. The primary is the party's own contest, so the party sets much of how it runs, while the general election is run by the state for all voters. Partial: one of the two elections described is approaching. (HSS-8.3)"]}]},{id:23,title:"The Young Republic",short:"Republic",parts:[{std:["HSS-8.4"],n:3,dur:95,dir:"Read the note. Answer out loud.",desc:"analyzing land ownership and the independent farmer as ideals of the new nation",html:()=>`<p class="big">Thomas Jefferson argued that a republic was safest in the hands of people who owned the land they worked, because a farmer with his own ground answered to no landlord and no employer. Congress acted on that belief: it surveyed the western territory into square mile sections and sold them off, cutting the smallest parcel and the price down again and again so that ordinary families could buy in.</p>
     <table class="bigTable"><tr><th>Law</th><th>Smallest parcel you could buy</th><th>Price per acre</th></tr>
     <tr><td>1785 Land Ordinance</td><td>640 acres</td><td>$1.00</td></tr>
     <tr><td>1800 Land Act</td><td>320 acres</td><td>$2.00, paid over four years</td></tr>
     <tr><td>1820 Land Act</td><td>80 acres</td><td>$1.25, paid in cash</td></tr></table>
     <div class="figure">${ico("tractor",74)}${ico("wheat",74)}${ico("apple",74)}</div>`,qs:["Why did Congress keep shrinking the smallest parcel it would sell?","Explain the connection Jefferson drew between owning land and being a good citizen of a republic.","Name one group this ideal left out, and say how."],key:["To put land within reach of ordinary families rather than only speculators and the wealthy. At 640 acres the cash price alone was $640, which almost no farm family had, so the smaller parcels and the installment terms were how the ideal of a nation of landowners was meant to be made real. Partial: naming the smaller parcels with no arithmetic showing why 640 acres was out of reach is approaching. (HSS-8.4)","He held that a person who owned his own ground did not depend on a landlord, a creditor or an employer for his living, so he could vote his own judgment and could not be pressured or bought. A republic of dependent men, he thought, would be a republic whose votes belonged to whoever held their livelihood. Partial: naming independence with nothing said about votes being pressured or bought is approaching. (HSS-8.4)","Any accurate answer with the reasoning. The land being sold was taken from Native nations by treaty and by pressure, so one people's independence was built on another's dispossession. Enslaved people could own nothing at all. Married women in most states could not hold property in their own names. Wage workers in Eastern cities had no realistic path to a western farm. Partial: naming a group that was left out with no reasoning is approaching. (HSS-8.4)"]},{std:["HSS-8.5"],n:3,dur:95,dir:"Look at the chart. Answer out loud.",desc:"analyzing the Louisiana Purchase as an act of foreign policy and the constitutional question it raised",html:()=>`<p class="big">In 1803 Jefferson's envoys went to Paris to try to buy the port of New Orleans. France offered the whole Louisiana territory instead.</p>
     <table class="bigTable"><tr><th></th><th></th></tr>
     <tr><td>Price</td><td>$15 million</td></tr>
     <tr><td>Land</td><td>about 828,000 square miles, which roughly doubled the country</td></tr>
     <tr><td>Why France sold</td><td>it needed money for a European war and had lost its hold in the Caribbean</td></tr>
     <tr><td>Why the United States wanted New Orleans</td><td>western farmers shipped their crops down the Mississippi and out through that one port</td></tr>
     <tr><td>The problem</td><td>nothing in the Constitution says the president may buy territory</td></tr></table>
     <div class="figure">${ico("map",74)}${ico("wave",74)}${ico("coin",74)}</div>`,qs:["Why was one port worth sending envoys across the Atlantic over?","Jefferson had argued for years that the national government may do only what the Constitution lists. Explain the bind he was in, and how the purchase went through anyway.","Name one group for whom this purchase was not good news, and say why."],key:["Because the Mississippi was the only cheap route to market for everything grown west of the Appalachians, and whoever held New Orleans could close that route or tax it at will. Control of the mouth of the river decided whether western farming was worth doing. Partial: naming the river with nothing said about who could close or tax the route is approaching. (HSS-8.5)","Buying territory is not among the enumerated powers, so by his own strict reading he had no authority to do it. He went ahead anyway, reasoning from the president's power to make treaties and from the plain interest of the country, and the Senate ratified the treaty. It is the clearest early case of a strict constructionist using implied power when the opportunity was too good to refuse. Partial: noting the contradiction with nothing said about how he justified it is approaching. (HSS-8.5)","The Native nations living in that territory, whose land was bought and sold between two distant governments without their consent and who would face steady pressure and removal afterward. Also acceptable: the Spanish and French residents of New Orleans, whose legal status and property claims were suddenly in the hands of a new government. Partial: naming the nations with nothing said about their consent never being asked is approaching. (HSS-8.5)"]},{std:["HSS-8.6"],n:3,dur:95,dir:"Look at the chart. Answer out loud.",desc:"analyzing the economic effect of canal building in the Northeast",html:()=>`<p class="big">The Erie Canal opened in 1825, running 363 miles from Albany to Buffalo and linking the Hudson River to the Great Lakes.</p>
     <table class="bigTable"><tr><th>Moving a ton of freight from Buffalo to New York City</th><th>Before the canal</th><th>After the canal</th></tr>
     <tr><td>Cost</td><td>about $100</td><td>about $10</td></tr>
     <tr><td>Time</td><td>about three weeks</td><td>about eight days</td></tr></table>
     <p class="big">New York City's population was about 123,000 in 1820 and about 515,000 in 1850.</p>
     <div class="figure">${ico("canoe",74)}${ico("wheat",74)}${ico("coin",74)}</div>`,qs:["A barrel of flour milled in Rochester now reached New York for a tenth of the old cost. Name two effects of that.","Why would a canal in upstate New York make New York City grow faster than Boston or Philadelphia?","Who in the Northeast would have had reason to dislike the canal?"],key:["Any two: western New York and then the Great Lakes states became commercial farming country, because their grain could finally reach a market; food in Eastern cities got cheaper, which made city wages go further; New York merchants, warehouses and banks gained an enormous volume of trade; and farmers in rocky New England could not match the prices, so many left farming for mill work or moved west. Partial: one effect named is approaching. (HSS-8.6)","Because the canal gave New York the only cheap water route from the Atlantic through the Appalachians to the interior, so goods going in either direction passed through its harbor. The other ports had no comparable route, so the trade and the business that came with it concentrated in one city. Partial: naming the canal with no comparison to the other ports is approaching. (HSS-8.6)","New England farmers undercut by cheap western grain, and the teamsters, wagon builders, innkeepers and turnpike companies along the old overland routes whose business the canal took. Boston and Philadelphia merchants also lost ground, which is why both cities rushed to build canals and then railroads of their own. Partial: one group of losers named is approaching. (HSS-8.6)"]}]},{id:24,title:"Three Different Countries",short:"Sections",parts:[{std:["HSS-8.7"],n:3,dur:100,dir:"Look at the chart. Answer out loud.",desc:"analyzing the social structure of the South and where power sat within it",html:()=>`<p class="big">Who lived in the South in 1860. The region's whole population was about 11 million.</p>
     <table class="bigTable"><tr><th>Group</th><th>About how many</th></tr>
     <tr><td>white families who held 20 or more people in slavery</td><td>fewer than 50,000 families</td></tr>
     <tr><td>white families who held between 1 and 19</td><td>about 340,000 families</td></tr>
     <tr><td>white families who held no one in slavery</td><td>about three quarters of all white families</td></tr>
     <tr><td>free Black southerners</td><td>about 260,000</td></tr>
     <tr><td>people held in slavery</td><td>about 3,950,000</td></tr></table>
     <div class="figure">${ico("wheat",74)}${ico("cow",74)}${ico("chest",74)}</div>`,qs:["Most white southerners owned no one. Who then held the political and economic power, and how do you know from this chart?","In South Carolina and Mississippi, people held in slavery were a majority of the population. What would that mean for how those states were governed?","Free Black southerners were legally free. Name two ways their freedom was still restricted."],key:["The small group of large slaveholders. They held the best land, the great majority of the region's capital in the form of enslaved people, and the seats in state legislatures and in Congress, so a few tens of thousands of families set policy for eleven million people. The chart shows how tiny that group was relative to the whole. Partial: naming the group with no account of how small it was relative to the whole is approaching. (HSS-8.7)","That the majority of people in those states had no vote, no legal rights and every reason to want the system gone, so the state governments were run by and for a minority and devoted real effort to control: pass laws, patrols, restrictions on gathering and on literacy. A government can be a republic for one part of its population and not for the rest. Partial: noting who could not vote with nothing said about a republic for one part of the population only is approaching. (HSS-8.7)","Any two accurate restrictions: they had to carry papers proving their free status, they could not vote in most Southern states, they could not testify against a white person in court, they were barred from many trades, some states required a sponsor or forbade them to move in at all, and a free person could be seized and sold on a false claim with little recourse. Partial: one restriction named is approaching. (HSS-8.7)"]},{std:["HSS-8.8"],n:3,dur:95,dir:"Look at the chart. Answer out loud.",desc:"analyzing federal Indian removal policy and the resistance to it",html:()=>`<p class="big">The Cherokee Nation had a written constitution, a national council, a newspaper printed in its own alphabet, and farms and towns in Georgia. Gold was found on its land in 1829.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1830</td><td>Congress passes the Indian Removal Act, authorizing exchanges of eastern land for land west of the Mississippi</td></tr>
     <tr><td>1831</td><td>The Supreme Court declines to hear a Cherokee case for lack of jurisdiction</td></tr>
     <tr><td>1832</td><td>In Worcester v. Georgia the Court holds Georgia's laws have no force in Cherokee territory</td></tr>
     <tr><td>1835</td><td>A small unauthorized faction signs a removal treaty the Cherokee council rejects</td></tr>
     <tr><td>1838</td><td>The army forces about 16,000 Cherokee west; roughly a quarter die on the way or soon after</td></tr></table>
     <div class="figure">${ico("map",74)}${ico("books",74)}${ico("mountain",74)}</div>`,qs:["The Cherokee won in the Supreme Court in 1832 and were removed anyway six years later. What does that tell you about how the system worked then?","Name two ways the Cherokee Nation resisted before 1838, besides fighting.","Why did pressure on Cherokee land rise sharply after 1829?"],key:["That a court ruling means little when no branch will enforce it. The Court held for the Cherokee, Georgia ignored the decision, and the president did not use federal power to make the state comply, so the practical outcome was set by whoever was willing to act rather than by the law. Partial: naming the ruling with nothing said about enforcement is approaching. (HSS-8.8)","Any two: they wrote a constitution and ran a national government to show they were a nation entitled to deal by treaty, they took their case to the federal courts twice, they published a newspaper arguing their case to an American audience, they sent delegations to Washington, they refused to ratify the 1835 treaty, and many hired lawyers or petitioned Congress. Partial: one action named is approaching. (HSS-8.8)","Gold was found on their land in 1829, and Georgia and its settlers wanted both the gold and the farmland. An economic prize turned a long standing pressure into an immediate campaign, and the state passed laws asserting authority over Cherokee territory. Partial: naming the gold with nothing said about the farmland or the state's laws is approaching. (HSS-8.8)"]},{std:["HSS-8.9"],n:3,dur:95,dir:"Read the note. Answer out loud.",desc:"analyzing Frederick Douglass's abolition work and his argument from the nation's founding ideals",html:()=>`<p class="big">Frederick Douglass was born into slavery in Maryland around 1818. He learned to read in secret, escaped north at twenty, and spent the rest of his life arguing in public for the end of slavery. He published his own account of his life in 1845, founded a newspaper, the North Star, in 1847, and spoke to audiences across the North and in Britain. His standing argument was that the Declaration of Independence already stated the case against slavery, and that the nation was refusing to read its own words.</p>
     <div class="figure">${ico("books",74)}${ico("pencil",74)}${ico("torch",74)}</div>`,qs:["Why would writing and publishing his own life story be an effective move against slavery?","Why found his own newspaper when antislavery papers already existed?","Explain the argument he made from the Declaration of Independence, and say why it was hard to answer."],key:["Because defenders of slavery claimed that enslaved people were content and incapable, and a detailed first hand account by a man who had lived it contradicted that directly. Naming places and people made it checkable rather than hearsay, though it also exposed him to recapture. A reader could no longer treat slavery as a distant abstraction. Partial: calling the book moving with nothing said about what claim it contradicted is approaching. (HSS-8.9)","So that Black Americans spoke for themselves rather than being spoken for. He had been treated by some white allies as an exhibit rather than a colleague, and a paper he owned set its own arguments and its own priorities. It also demonstrated the very capability that slavery's defenders denied. Partial: naming the paper with nothing said about speaking for themselves is approaching. (HSS-8.9)","He argued the country had already declared that all men are created equal and hold an unalienable right to liberty, so slavery was not merely wrong, it broke the nation's own founding commitment. It was hard to answer because it required no appeal to any outside authority: a defender had to either deny the Declaration's words or deny that enslaved people were men. Partial: naming the argument with nothing said about why it was hard to answer is approaching. (HSS-8.9)"]}]},{id:25,title:"War, Law and Industry",short:"War and After",parts:[{std:["HSS-8.10"],n:3,dur:100,dir:"Look at the chart. Answer out loud.",desc:"comparing the resources of the two sides and reasoning from them to strategy and outcome",html:()=>`<p class="big">What each side had in 1861.</p>
     <table class="bigTable"><tr><th></th><th>Union</th><th>Confederacy</th></tr>
     <tr><td>Population</td><td>about 22 million</td><td>about 9 million, of whom about 3.5 million were enslaved</td></tr>
     <tr><td>Factories</td><td>about 110,000</td><td>about 18,000</td></tr>
     <tr><td>Miles of railroad</td><td>about 22,000</td><td>about 9,000</td></tr>
     <tr><td>Share of the nation's firearms production</td><td>about 97 percent</td><td>about 3 percent</td></tr>
     <tr><td>Share of the nation's cotton crop</td><td>almost none</td><td>almost all</td></tr></table>
     <div class="figure">${ico("flag",74)}${ico("truck",74)}${ico("wheat",74)}</div>`,qs:["Given these numbers, what kind of war did the Confederacy need, and what kind did the Union need?","The Confederacy expected its cotton to bring Britain into the war on its side. Why did that not work?","A third of the Confederate population was enslaved. How did that cut both ways for the Confederacy?"],key:["The Confederacy needed a short war: hold its territory, make the cost high enough that Northern voters gave up, and win recognition from Europe. The Union needed a long one that brought its advantages to bear, which meant blockading the coast, taking the Mississippi, and wearing down armies and railroads it could replace and the other side could not. Partial: one side's strategy described is approaching. (HSS-8.10)","Britain had stockpiled cotton before the war and then turned to Egypt and India, its workers and public were strongly against slavery, and it was unwilling to fight the United States over a government it never recognized. Expecting one commodity to decide another nation's policy turned out to be a serious misreading. Partial: one reason named is approaching. (HSS-8.10)","Enslaved labor kept farms and war production going while white men went to the army, which is how a smaller population fielded large forces. But those same people had every reason to want the Confederacy to lose, and hundreds of thousands left plantations as Union armies approached, taking their labor with them and then joining the Union army. The system that supplied the Confederacy also drained it. Partial: one side of the double effect named is approaching. (HSS-8.10)"]},{std:["HSS-8.11"],n:3,dur:95,dir:"Read the note. Answer out loud.",desc:"analyzing what freedpeople did first with freedom and what those choices show",html:()=>`<p class="big">In the first years after 1865, people who had been freed acted fast and acted on their own account. They placed thousands of advertisements in newspapers looking for parents, children, husbands and wives who had been sold away. They went to county offices to have marriages recorded in law for the first time. They pooled wages to buy land and to pay teachers, and more than a thousand schools were running in the South within five years. They refused contracts that paid nothing, walked off places that would not pay, and in 1867 and 1868 they registered to vote in overwhelming numbers.</p>
     <div class="figure">${ico("hands",74)}${ico("books",74)}${ico("key",74)}</div>`,qs:["Searching for family came first for enormous numbers of people. What does that tell you about what slavery had done?","Why would making a marriage legal matter so much to a couple who had considered themselves married for twenty years?","Freedpeople paid for schools out of their own wages while they were desperately poor. Why put the money there?"],key:["That the sale of individuals had torn families apart as a matter of routine, and that the bonds survived it. People who had been treated in law as property with no kin had in fact kept track of mothers, children and spouses for decades and went looking the moment they could. It shows slavery's cruelty and the limits of what it managed to destroy. Partial: naming the searching with nothing said about what it shows is approaching. (HSS-8.11)","Because under slavery a marriage had no standing in law: either partner could be sold away and no court would stop it, and children had no legally recognized father. A recorded marriage meant the state now had to acknowledge the family, which affected inheritance, custody, pensions and the simple fact of not being separable at someone else's decision. Partial: saying they wanted to marry with no account of what legal standing changed is approaching. (HSS-8.11)","Because reading and writing had been withheld by law, and literacy was what let a person check a contract, keep accounts, read a ballot and not be cheated. Schooling was treated as the practical foundation of every other kind of freedom, and as something that could not be taken back once a child had it. Partial: saying school is good with nothing said about what literacy protected them from is approaching. (HSS-8.11)"]},{std:["HSS-8.12"],n:3,dur:95,dir:"Read the note. Answer out loud.",desc:"analyzing the rise of the large corporation and what it changed about the economy",html:()=>`<p class="big">Before the war, most American businesses were owned by one person or a partnership and employed a handful of workers. After it, a new form took over. Andrew Carnegie's steel company bought its own iron mines, its own coal, its own ships and its own railroads, so that every step from ore to finished rail happened inside one firm. John D. Rockefeller's Standard Oil instead bought up competing refineries until it controlled roughly 90 percent of American refining. By 1900 a single corporation could employ tens of thousands of people and raise money by selling shares to thousands of investors who never set foot in it.</p>
     <div class="figure">${ico("box",74)}${ico("coin",74)}${ico("moneybag",74)}</div>`,qs:["Carnegie bought up his suppliers and Rockefeller bought up his competitors. What advantage was each one after?","Selling shares to strangers let a company raise money no partnership could. What does that change about who makes decisions and who takes the risk?","Name one way the arrival of companies this large changed life for people who did not own any part of them."],key:["Carnegie was after cost and control: owning every step meant no supplier could raise his price or fail to deliver, and he could undersell anyone who had to buy at market. Rockefeller was after the market itself: with most refining in one set of hands he could set prices and dictate shipping rates to the railroads. One strategy controls the chain, the other controls the field. Partial: one of the two strategies described is approaching. (HSS-8.12)","Ownership separates from management. Thousands of shareholders own the firm but a small group of managers runs it, and the owners risk only the money they put in rather than everything they have. That made it possible to assemble the enormous sums that steel mills and rail networks needed, and it also meant the people deciding and the people bearing the loss were no longer the same people. Partial: naming the shareholders with nothing said about who bears the loss is approaching. (HSS-8.12)","Any supported answer: workers bargained with a distant company rather than a known employer, and a firm that size could replace them or wait out a strike; consumers got cheaper steel and kerosene but faced prices one firm could set; small competitors and local shops were undersold out of business; farmers and shippers depended on rates set by firms they could not reach; and the sheer size of these companies turned into political influence, which is what later brought demands for regulation. Partial: a group named with no account of how the firms affected them is approaching. (HSS-8.12)"]}]},{id:26,title:"Clean Leaves and a Grafted Branch",short:"Heredity",parts:[{std:["LS3"],n:3,dur:90,dir:"Look at the chart. Answer out loud.",desc:"tracing a change in a gene through the protein it codes for to the trait that results",html:()=>`<p class="big">Apple trees in this orchard carry four versions of one gene. The gene codes for a receptor protein that sits on the cell surface and recognizes the scab fungus, which triggers the leaf's defense.</p>
     <table class="bigTable"><tr><th>Gene version</th><th>Protein the gene codes for</th><th>Leaves after a wet spring</th></tr>
     <tr><td>R1, unchanged</td><td>full length receptor, recognizes the fungus well</td><td>no spots</td></tr>
     <tr><td>R2, one base changed in the recognition region</td><td>full length receptor, binds the fungus weakly</td><td>a few small spots</td></tr>
     <tr><td>R3, two bases inserted</td><td>protein ends early, no receptor reaches the cell surface</td><td>heavy spotting, leaves drop</td></tr>
     <tr><td>R4, one base changed, same amino acid results</td><td>receptor identical to R1's</td><td>no spots</td></tr></table>
     <div class="figure">${ico("apple",74)}${ico("leaf",74)}${ico("tree",74)}</div>`,qs:["R4 is a real change in the DNA and the leaves are identical to R1's. Explain why, using the protein column.","R2 and R3 both spot, and not to the same degree. Use the protein column to explain the difference.","A branch of R1 is grafted onto an R3 rootstock. The leaves on the grafted branch stay clean. Explain that in terms of genes and proteins."],key:["The change in R4 falls at a position where the altered DNA still specifies the same amino acid, so the receptor built from it is identical to R1's, folds the same way and recognizes the fungus the same way. A trait follows the protein, not the DNA sequence by itself, so a change that leaves the protein unaltered leaves the trait unaltered. Partial: saying the R4 change makes no difference, with nothing said about the altered DNA still specifying the same amino acid, is approaching. (LS3)","R2 still builds a full length receptor, so it folds and reaches the cell surface and still recognizes the fungus, only weakly, and a weak but real defense gives a few spots instead of none. R3 ends the protein early so no receptor is built at all, there is no defense, and the leaves spot heavily and drop. How much of the protein's structure survives the change decides how much of the trait survives. Partial: saying R3 is the worse change, with nothing said about R2's receptor still reaching the surface and working weakly, is approaching. (LS3)","Grafting joins two plants but does not mix their genes. Every cell in the grafted branch carries R1 and builds the working receptor, so the leaves that branch grows are defended. The rootstock's cells carry R3 and build none, but they are not the cells making those leaves. A gene acts inside the cells that carry it. Partial: answering that the branch stays clean because it is R1, with nothing said about a gene acting only inside the cells that carry it, is approaching. (LS3)"]}]},{id:27,title:"The Quarry Behind the Orchard",short:"Evolution",parts:[{std:["LS4"],n:3,dur:90,dir:"Study both charts. Answer out loud.",desc:"reading the fossil sequence, skeletal counts and embryo stages as evidence of common ancestry",html:()=>`<p class="big">A quarry cut into the hill behind the orchard. Layers pile up newest on top.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Rock</th><th>Fossils in it</th></tr>
     <tr><td>W, 0 to 2 m</td><td>loam</td><td>deer bones and oak leaves like those alive today</td></tr>
     <tr><td>X, 2 to 9 m</td><td>siltstone</td><td>a horse sized grazer with one toe per foot and tall grinding teeth</td></tr>
     <tr><td>Y, 9 to 20 m</td><td>claystone</td><td>a sheep sized animal with three toes per foot and low crowned teeth</td></tr>
     <tr><td>Z, 20 to 34 m</td><td>sandstone</td><td>a dog sized leaf eater with four toes on each front foot</td></tr></table>
     <p class="big">Bones in the neck, counted.</p>
     <table class="bigTable"><tr><th>Animal</th><th>Bones in the neck</th><th>Neck length</th></tr>
     <tr><td>giraffe</td><td>7</td><td>about 2 m</td></tr>
     <tr><td>human</td><td>7</td><td>about 12 cm</td></tr>
     <tr><td>mouse</td><td>7</td><td>about 1 cm</td></tr>
     <tr><td>blue whale</td><td>7</td><td>short and stiff</td></tr>
     <tr><td>swan, a bird rather than a mammal</td><td>23</td><td>about 1 m</td></tr></table>
     <div class="figure">${ico("horse",74)}${ico("deer",74)}${ico("mouse",74)}</div>`,qs:["Read the quarry layers from oldest to youngest and describe the change in the feet and in the teeth.","Four mammals with wildly different necks all have 7 neck bones, and the swan has 23. What does that pattern show, and why does the swan row matter to the argument?","A pig embryo and a chicken embryo both grow a notochord and a row of repeated muscle blocks down the back before anything else about them is recognizable. Explain how that fits with the two charts."],key:["Oldest first: Z sandstone with a small four toed leaf eater, then Y claystone with a three toed animal with low crowned teeth, then X siltstone with a one toed grazer with tall grinding teeth, then W loam with forms alive today. Toes are reduced from four to three to one, and teeth change from low crowned, which suits soft leaves, to tall and hard wearing, which suits gritty grass. The layers hold a sequence of related forms changing over tens of millions of years. Partial: the four layers in the right order with the change described in the feet or the teeth but not both is approaching. (LS4)","A neck 200 times longer than another, built from the same seven bones, shows that the count is inherited rather than set by the job the neck does: lengthening the neck lengthened the bones instead of adding more. The swan matters because it proves more bones are perfectly possible, so seven is not a requirement of necks in general. It is a feature mammals share because they inherited it from a common ancestor, which is what makes it evidence. Partial: saying the seven bones are inherited with nothing said about the swan showing that more bones are possible is approaching. (LS4)","Those structures appear in both embryos before either is a pig or a chicken, so they cannot be explained by what the adult animal does for a living. Shared early development points to a shared set of inherited instructions. The quarry gives the sequence of forms in time, the neck counts give a shared plan in adults, and the embryos give the same plan in development, and all three point to common ancestry. Partial: saying the embryos look alike early on, with nothing said about that ruling out the adult's way of life as the cause, is approaching. (LS4)"]},{std:["LS4"],n:3,dur:90,dir:"Study both sets of numbers. Work on your paper and answer out loud.",desc:"explaining natural selection from trial data and distinguishing it from artificial selection",html:()=>`<p class="big">Codling moths in this orchard have been met with the same spray at the same dose every season. Two hundred moths are tested each generation.</p>
     <table class="bigTable"><tr><th>Generation</th><th>Died</th><th>Survived</th></tr>
     <tr><td>1</td><td>188</td><td>12</td></tr>
     <tr><td>4</td><td>151</td><td>49</td></tr>
     <tr><td>8</td><td>96</td><td>104</td></tr>
     <tr><td>12</td><td>44</td><td>156</td></tr></table>
     <p class="big">The orchard's own apple is a different story. For sixty years growers took cuttings only from the seedlings with the largest, sweetest fruit. Average fruit mass rose from 48 g in the wild crab apple it began as to 190 g today.</p>
     <div class="figure">${ico("apple",74)}${ico("apple",74)}${ico("bee",74)}</div>`,qs:["Explain why spraying the same dose every season produces the change in the chart. Say what the spray does and does not do to an individual moth.","Work out the percentage surviving in generation 1 and in generation 12, and state what has to be true of resistance for the change to carry to the next generation.","Compare the moths with the apple. In which case did people choose the parents, and in which case did people change the conditions and let survival do the choosing?"],key:["Resistance already varies among the moths before any spray is used. The spray kills the least resistant and leaves the most resistant alive to breed, so each generation is bred from survivors and the share of resistant moths climbs. The spray does not make a moth resistant: it only decides which of the moths already there get to reproduce. Natural selection acts on variation that is present, it does not create it. Partial: describing the survivors breeding with nothing said about the spray not making any individual moth resistant is approaching. (LS4)","Generation 1: 12 of 200, which is 6 percent. Generation 12: 156 of 200, which is 78 percent. Resistance has to be heritable, carried in the genes and passed to offspring. If it came from something that happened during a moth's own life, the survivors' young would start over at 6 percent and the chart would stay flat. Partial: working out the 6 and 78 percent with nothing said about resistance having to be heritable is approaching. (LS4)","People chose the parents for the apple: they decided which seedlings to take cuttings from, which is artificial selection, and sixty years of it moved fruit mass from 48 g to 190 g. With the moths people changed the conditions by adding a spray and then let survival sort the population, which is natural selection even though a human action set it off. The mechanism is the same in both; who or what does the selecting differs. Partial: naming the apple as the case where people chose the parents with nothing said about the moths being natural selection set off by a human action is approaching. (LS4)"]}]},{id:28,title:"Sun Over the Rows",short:"Universe",parts:[{std:["MS-ESS1"],n:3,dur:85,dir:"Look at the chart. Answer out loud.",desc:"explaining the seasonal cycle from measurements and the part gravity plays in orbits",html:()=>`<p class="big">The orchard keeps a record of the sun at noon and the length of the day.</p>
     <table class="bigTable"><tr><th>Date</th><th>Height of the sun at noon</th><th>Hours of daylight</th></tr>
     <tr><td>March 20</td><td>52 degrees</td><td>12 h 06 m</td></tr>
     <tr><td>June 21</td><td>75 degrees</td><td>14 h 48 m</td></tr>
     <tr><td>September 22</td><td>52 degrees</td><td>12 h 10 m</td></tr>
     <tr><td>December 21</td><td>29 degrees</td><td>9 h 24 m</td></tr></table>
     <div class="figure">${ico("sun",74)}${ico("tree",74)}${ico("leaf",74)}</div>`,qs:["Describe the pattern in both columns across the year and name what causes it.","A picker says June is warmer because Earth is closer to the sun then. Use the chart to show what is actually doing the work.","An apple falls straight down and the moon does not fall onto Earth. Name the force acting in both cases and explain why the outcomes differ."],key:["The sun climbs higher at noon and the day lengthens from December to June, then both fall back, and the two middle dates match because they are the same point in the cycle passed in opposite directions. The cause is the tilt of Earth's axis, which stays pointed the same way in space while Earth travels around the sun, so each hemisphere leans toward the sun for half the year and away for the other half. Partial: describing the pattern across the year with the cause given as distance from the sun rather than the tilt of the axis is not yet there; describing it and naming the tilt without the axis staying pointed the same way is approaching. (MS-ESS1)","The chart shows the sun 75 degrees up for nearly 15 hours in June and 29 degrees up for under 10 hours in December. A high sun spreads the same energy over a smaller patch of ground, and a longer day delivers it for more hours, which is enough to explain the difference without moving Earth at all. Distance cannot be the cause anyway, since both hemispheres share the same distance and have opposite seasons. Partial: quoting the sun's height and the day length with nothing said about a high sun spreading its energy over a smaller patch is approaching. (MS-ESS1)","Gravity in both cases. The apple starts at rest, so the only motion gravity can give it is straight down toward Earth's center. The moon is already moving sideways at about a kilometer per second, so gravity bends that motion into a curve instead of pulling it straight in, and the curve closes into an orbit. The moon is falling; it just keeps missing. Partial: naming gravity in both cases with nothing said about the moon's sideways motion being bent into a curve is approaching. (MS-ESS1)"]},{std:["MS-ESS1"],n:3,dur:85,dir:"Use both charts. Work on your paper and tell your teacher each answer.",desc:"comparing size against distance for sky objects and reading a gap in the rock record",html:()=>`<p class="big">Three objects seen from the orchard.</p>
     <table class="bigTable"><tr><th>Object</th><th>Diameter in km</th><th>Distance in km</th></tr>
     <tr><td>the moon</td><td>3,475</td><td>384,000</td></tr>
     <tr><td>Mars at its closest</td><td>6,780</td><td>56,000,000</td></tr>
     <tr><td>the sun</td><td>1,392,000</td><td>150,000,000</td></tr></table>
     <p class="big">The quarry wall again, with the rock in each unit dated.</p>
     <table class="bigTable"><tr><th>Unit, top to bottom</th><th>Age of the rock</th><th>Fossil used to recognize it</th></tr>
     <tr><td>loam</td><td>9,000 years</td><td>none</td></tr>
     <tr><td>siltstone</td><td>15 million years</td><td>one toed grazer</td></tr>
     <tr><td>claystone</td><td>33 million years</td><td>three toed animal</td></tr>
     <tr><td>sandstone</td><td>50 million years</td><td>four toed leaf eater</td></tr>
     <tr><td>tilted limestone, its top cut flat before the sandstone was laid on it</td><td>300 million years</td><td>sea lilies</td></tr></table>
     <div class="figure">${ico("moon",74)}${ico("globe",74)}${ico("mountain",74)}</div>`,qs:["The sun's diameter is about 400 times the moon's. Compare the two distances and explain why the two look nearly the same size in the orchard sky.","Mars is about twice the moon's diameter. Work out how many times farther away it is at its closest, and explain why it still looks like a point of light rather than a disk.","Explain how 300 million year limestone can sit directly beneath 50 million year sandstone, and say what the flat cut between them records."],key:["150,000,000 divided by 384,000 is about 390, so the sun is about 390 times as far away as the moon while being about 400 times as wide. Apparent size depends on the ratio of width to distance, and those two ratios nearly cancel, so the two objects cover almost the same patch of sky. The coincidence is what makes a total solar eclipse possible at all. Partial: working out the 390 with nothing said about the two ratios nearly cancelling is approaching. (MS-ESS1)","56,000,000 divided by 384,000 is about 146, so Mars is roughly 146 times farther away while being only about 2 times wider. Its width divided by its distance is therefore about 73 times smaller than the moon's, so it covers a patch of sky too small for the eye to see as a disk and reads as a bright point. Size alone never tells you how large something will look. Partial: working out the 146 with nothing said about width divided by distance deciding how large something looks is approaching. (MS-ESS1)","Nothing that formed between 300 and 50 million years ago is present here, either because nothing was deposited for that span or because what was deposited was later stripped away. The limestone was laid down, then tilted, then its top was eroded flat, and only afterward was the sandstone laid across the cut. That flat surface records a gap of about 250 million years, so the rock record at one place is a record with missing pages, not a continuous one. (MS-ESS1) Rating guide for this part, because these three questions sit above the grade-level floor of MS-ESS1. 3: the student uses the ratio of width to distance to explain how large something looks, and reads the flat cut as time missing from the rock record. 2: works one of the two distance comparisons but judges apparent size from width alone, or sees the gap without saying what it records. 1: does not bring distance into the comparison at all. Where the count of right answers and this guide disagree, rate from the guide and write the count in Notes."]}]},{id:29,title:"Power for Cold Storage",short:"Human Impact",parts:[{std:["MS-ESS3"],n:3,dur:95,dir:"Look at the chart. Work on your paper and answer out loud.",desc:"separating population growth from per household consumption in total demand on a resource",html:()=>`<p class="big">Electricity in the apple growing county, from the utility's own figures. The last row is the utility's projection.</p>
     <table class="bigTable"><tr><th>Year</th><th>Households</th><th>kWh per household per year</th><th>Total</th></tr>
     <tr><td>1990</td><td>20,000</td><td>7,800</td><td>156 GWh</td></tr>
     <tr><td>2005</td><td>32,000</td><td>9,500</td><td>304 GWh</td></tr>
     <tr><td>2020</td><td>44,000</td><td>8,900</td><td>391.6 GWh</td></tr>
     <tr><td>2035, projected</td><td>56,000</td><td>8,000</td><td>448 GWh</td></tr></table>
     <div class="figure">${ico("lamp",74)}${ico("cabin",74)}${ico("truck",74)}</div>`,qs:["Total electricity went up by a factor of about 2.5 from 1990 to 2020. Work out how much of that came from more households and how much from more use per household.","The 2035 projection cuts per household use by 10 percent and the total still rises. Explain, then work out what per household figure would hold the total at the 2020 level.","Name two effects on Earth's systems of a larger total demand for electricity, and say which of them efficiency alone reduces and which it does not."],key:["Households went from 20,000 to 44,000, a factor of 2.2. Per household use went from 7,800 to 8,900 kWh, a factor of about 1.14. Multiplied together, 2.2 times 1.14 is about 2.5, which is the rise in the total. Nearly all of the increase came from more households, and about a seventh of it from each household using more. Partial: naming both factors with only one of the two multipliers worked out is approaching. (MS-ESS3)","Per household use falls from 8,900 to 8,000 kWh, a drop of about 10 percent, while households rise from 44,000 to 56,000, a rise of about 27 percent. The larger rise outweighs the smaller drop, so the product goes up. To hold the total at 391.6 GWh with 56,000 households, each would have to use 391,600,000 divided by 56,000, which is about 7,000 kWh, a cut of more than 21 percent rather than 10. Partial: explaining why the total still rises with the 7,000 kWh figure not worked out is approaching. (MS-ESS3)","Any two: more fuel burned adds carbon dioxide and other gases to the atmosphere, which changes the climate system; generation and cooling draw heavily on fresh water; more land and rock are disturbed for fuel, for panels or turbines, and for transmission lines; and waste heat and ash or spent fuel have to go somewhere. Efficiency reduces the demand each household makes, so it reduces fuel burned per home, but it cannot reduce the number of homes, and the chart shows that growth in households has been the larger factor. Partial: two effects named with nothing said about efficiency being unable to reduce the number of homes is approaching. (MS-ESS3)"]}]},{id:30,title:"On the Packing Floor",short:"Forces",parts:[{std:["MS-PS2"],n:3,dur:85,dir:"Use both charts. Work on your paper and answer out loud.",desc:"applying the third law to a push between two objects and relating force and mass to motion",html:()=>`<p class="big">A picker stands on a wheeled platform at the end of a row and throws a full crate forward to a helper.</p>
     <table class="bigTable"><tr><th>Object</th><th>Mass</th><th>Speed just after the throw</th></tr>
     <tr><td>crate</td><td>15 kg</td><td>4 m/s forward</td></tr>
     <tr><td>picker and platform</td><td>60 kg</td><td>1 m/s backward</td></tr></table>
     <p class="big">Inside the packing house, a loaded bin is pushed across the smooth floor.</p>
     <table class="bigTable"><tr><th>Trial</th><th>Push</th><th>Mass</th><th>Acceleration</th></tr>
     <tr><td>1</td><td>60 N</td><td>30 kg</td><td>2 m/s each second</td></tr>
     <tr><td>2</td><td>60 N</td><td>60 kg</td><td>1 m/s each second</td></tr>
     <tr><td>3</td><td>150 N</td><td>30 kg</td><td>5 m/s each second</td></tr>
     <tr><td>4</td><td>90 N</td><td>45 kg</td><td>2 m/s each second</td></tr></table>
     <div class="figure">${ico("truck",74)}${ico("box",74)}${ico("tractor",74)}</div>`,qs:["The picker pushed only on the crate, and the platform rolled backward. Explain with Newton's third law and compare the sizes of the two forces.","Multiply mass by speed for each row of the first chart. Say what you find, then predict the platform's speed if a 30 kg crate had left at the same 4 m/s.","Use the second chart. Name the pair of trials that isolates mass and the pair that isolates force, then check trial 4 against the rule."],key:["Forces come in pairs. The picker pushed forward on the crate, and the crate pushed backward on the picker with a force equal in size and opposite in direction at the same instant. The platform rolls freely, so that backward force moves the picker and platform away while the crate goes the other way. Nothing pushed on the platform except the crate. Partial: saying the crate pushed back, with nothing said about the two forces being equal in size and opposite in direction, is approaching. (MS-PS2)","Crate: 15 times 4 is 60. Picker and platform: 60 times 1 is also 60. The two quantities of motion match in size and point in opposite directions, which is what equal and opposite forces acting for the same length of time produce. A 30 kg crate at 4 m/s carries 120, so the 60 kg platform would have to leave at 120 divided by 60, which is 2 m/s backward. Partial: finding both products equal to 60 with the 2 m/s prediction not worked out is approaching. (MS-PS2)","Trials 1 and 2 hold the push at 60 N and double the mass from 30 kg to 60 kg, and the acceleration halves from 2 to 1. Trials 1 and 3 hold the mass at 30 kg and multiply the push by 2.5, from 60 N to 150 N, and the acceleration rises by the same factor, from 2 to 5. Trial 4 fits force equals mass times acceleration: 45 kg times 2 m/s each second is 90 N, which is the push listed. Partial: naming both pairs of trials with trial 4 not checked against force equals mass times acceleration is approaching. (MS-PS2)"]},{std:["MS-PS2"],n:3,dur:85,dir:"Use both charts. Work on your paper and answer out loud.",desc:"identifying what changes an electric force, relating weight to mass, and naming the field in a gap",html:()=>`<p class="big">Two strips of packing tape are pulled off the roll, which leaves them charged, and hung facing each other. The force pushing them apart is measured.</p>
     <table class="bigTable"><tr><th>Separation</th><th>Force</th></tr>
     <tr><td>2 cm</td><td>0.90 mN</td></tr>
     <tr><td>4 cm</td><td>0.23 mN</td></tr>
     <tr><td>6 cm</td><td>0.10 mN</td></tr>
     <tr><td>8 cm</td><td>0.06 mN</td></tr></table>
     <table class="bigTable"><tr><th>Seconds the strip was rubbed first</th><th>Force at 2 cm</th></tr>
     <tr><td>1</td><td>0.25 mN</td></tr>
     <tr><td>2</td><td>0.90 mN</td></tr>
     <tr><td>4</td><td>2.10 mN</td></tr></table>
     <p class="big">A 10 kg box of apples weighs 98.0 N on the scale at the sea level packing house and 97.9 N at the mountain shed 3,000 m up. On a world with twice Earth's mass and the same radius it would weigh 196 N.</p>
     <div class="figure">${ico("box",74)}${ico("globe",74)}${ico("apple",74)}</div>`,qs:["Use the first chart. Describe how the force between the strips changes with separation, and name the number pattern.","Use the second chart. Name the other thing that changes the force, and say which of the two factors you would change to raise the force most.","Explain all three weights of the 10 kg box, then name what fills the space between the box and Earth and carries the pull."],key:["The force falls fast as the strips are moved apart: 0.90 mN at 2 cm, 0.23 at 4 cm, 0.10 at 6 cm, 0.06 at 8 cm. Doubling the separation from 2 cm to 4 cm cut the force to about a quarter, and trebling it to 6 cm cut it to about a ninth, so the force falls off with the square of the distance. Partial: saying the force drops as the strips are separated, with nothing said about it falling with the square of the distance, is approaching. (MS-PS2)","The amount of charge on the strips, set here by how long each was rubbed: 1 second gives 0.25 mN, 2 seconds 0.90 mN and 4 seconds 2.10 mN at the same 2 cm. Both factors matter, but distance is the stronger lever in this range, since halving the separation from 4 cm to 2 cm multiplied the force by about four while doubling the rubbing time from 2 s to 4 s multiplied it by only about 2.3. Partial: naming the charge as the second factor with no comparison made of which lever is stronger is approaching. (MS-PS2)","The box has the same 10 kg of matter in all three places. Weight is the gravitational force on it, which depends on its mass, the mass of the world, and the distance to that world's center. At 3,000 m the box is slightly farther from Earth's center, so the pull drops a little, 98.0 N to 97.9 N. Double the world's mass with the same radius and the pull doubles to 196 N. The space between holds a gravitational field, which is how the pull reaches the box with nothing touching it. Partial: explaining two of the three weights is approaching, and the small drop at 3,000 m is usually the one left out. (MS-PS2)"]}]},{id:31,title:"Ramp and Press",short:"Energy",parts:[{std:["MS-PS3"],n:4,dur:110,dir:"Use both charts. Work on your paper and tell your teacher each answer.",desc:"relating kinetic energy to mass and speed and stored energy to the arrangement of objects",html:()=>`<p class="big">A cart is let go down the loading ramp and its kinetic energy is measured at the bottom.</p>
     <table class="bigTable"><tr><th>Trial</th><th>Mass</th><th>Speed</th><th>Kinetic energy</th></tr>
     <tr><td>1</td><td>3 kg</td><td>2 m/s</td><td>6 J</td></tr>
     <tr><td>2</td><td>6 kg</td><td>2 m/s</td><td>12 J</td></tr>
     <tr><td>3</td><td>3 kg</td><td>4 m/s</td><td>24 J</td></tr>
     <tr><td>4</td><td>3 kg</td><td>10 m/s</td><td>150 J</td></tr></table>
     <p class="big">Stored energy measured for a 20 kg crate in the loft and for the screw of the cider press.</p>
     <table class="bigTable"><tr><th>Arrangement</th><th>Stored energy</th></tr>
     <tr><td>crate 0.5 m above the floor</td><td>98 J</td></tr>
     <tr><td>crate 1.5 m above the floor</td><td>294 J</td></tr>
     <tr><td>crate 3.0 m above the floor</td><td>588 J</td></tr>
     <tr><td>press screw turned down 1 turn</td><td>12 J</td></tr>
     <tr><td>press screw turned down 3 turns</td><td>36 J</td></tr></table>
     <div class="figure">${ico("box",74)}${ico("apple",74)}</div>`,qs:["Compare trials 1 and 2. State how kinetic energy depends on mass at a fixed speed, and give the factor.","Compare trials 1, 3 and 4. State how kinetic energy depends on speed, then check trial 4 against your statement.","Use the crate rows. State how stored energy depends on height, and explain why a crate standing on the loft floor does not have a single stored energy that everyone would agree on.","The crate rows treble when the height trebles and the screw rows treble when the turns treble. Name what is being changed in each case, and say what the two have in common that makes the energy stored rather than kinetic."],key:["Doubling the mass from 3 kg to 6 kg at the same 2 m/s doubled the kinetic energy from 6 J to 12 J. At a fixed speed, kinetic energy is proportional to mass: the factor is 2, matching the factor on the mass. Partial: reading the 6 J and 12 J off the table with nothing said about energy being proportional to mass at a fixed speed is approaching. (MS-PS3)","Doubling the speed from 2 to 4 m/s multiplied the energy by four, 6 J to 24 J, so kinetic energy goes up with the square of the speed. Trial 4 is five times the speed of trial 1, so it should be twenty five times the energy: 25 times 6 J is 150 J, which is exactly what the chart lists. Partial: naming the squared relationship with trial 4 not checked against it is approaching. (MS-PS3)","Trebling the height from 0.5 m to 1.5 m trebled the stored energy from 98 J to 294 J, and six times the height gave six times the energy, 588 J at 3.0 m, so stored energy here is proportional to height. A crate on the loft floor has zero stored energy measured from the loft floor, but a positive amount measured from the packing floor below, and more again measured from the yard. Stored energy belongs to an arrangement of two objects and a chosen reference position, so the position has to be named before a number means anything. Partial: describing the proportion to height with nothing said about the reference position having to be named is approaching. (MS-PS3)","The crate rows change the distance between the crate and Earth. The screw rows change how far the screw has been driven into the pressed pulp, which changes the distance between the parts of the press and the squeezed material. In both cases what changed is the relative position of objects that attract or push on each other, and nothing is moving once it is set, so the energy is in the arrangement rather than in motion. Partial: naming what is changed in both cases with nothing said about the energy being in the arrangement rather than in motion is approaching. (MS-PS3)"]}]},{id:32,title:"Sound Across the Rows",short:"Waves",parts:[{std:["MS-PS4"],n:3,dur:80,dir:"Look at the chart. Work on your paper and answer out loud.",desc:"relating amplitude to the energy in a wave and using wavelength and frequency to find wave speed",html:()=>`<p class="big">A speaker in the packing shed is driven at four settings. A meter 10 m away records the energy arriving.</p>
     <table class="bigTable"><tr><th>Setting</th><th>Swing of the cone</th><th>Wavelength in air</th><th>Cycles per second</th><th>Energy at the meter</th></tr>
     <tr><td>A</td><td>0.2 mm</td><td>1.70 m</td><td>200</td><td>1 unit</td></tr>
     <tr><td>B</td><td>0.4 mm</td><td>1.70 m</td><td>200</td><td>4 units</td></tr>
     <tr><td>C</td><td>0.6 mm</td><td>1.70 m</td><td>200</td><td>9 units</td></tr>
     <tr><td>D</td><td>0.6 mm</td><td>0.85 m</td><td>400</td><td>9 units</td></tr></table>
     <div class="figure">${ico("megaphone",74)}${ico("radio",74)}</div>`,qs:["Compare A, B and C. Describe how the energy depends on amplitude, using the numbers.","Compare C and D. Work out the speed of the sound from each row, and say what has to change when the wavelength halves.","A worker across the orchard hears the tone, and no air arrives from the shed. Explain what does reach the worker."],key:["Amplitude trebled from 0.2 mm to 0.6 mm and the energy went up nine times, 1 unit to 9 units. Doubling it from 0.2 to 0.4 mm gave four times the energy. Energy goes up with the square of the amplitude, which is why amplitude is the part of a wave that carries the energy and the only one of the three numbers that changes it here. Partial: saying a louder sound carries more energy, with nothing said about the energy going up with the square of the amplitude, is approaching. (MS-PS4)","Speed is wavelength times cycles per second. C: 1.70 m times 200 is 340 m per second. D: 0.85 m times 400 is also 340 m per second. Sound travels at the same speed through the same air, so halving the wavelength forces the frequency to double. The energy did not change, because the amplitude did not. Partial: working out one of the two speeds, or both with nothing said about frequency having to double when the wavelength halves, is approaching. (MS-PS4)","The disturbance travels, not the air. The cone pushes the air next to it, that air pushes the air beyond it, and the compression passes along the row while each parcel of air springs back to where it started. Energy and the pattern of the wave arrive at the worker; the air itself stays near the shed. Partial: saying the sound travels through the air, with nothing said about each parcel of air springing back to where it started, is approaching. (MS-PS4)"]},{std:["MS-PS4"],n:3,dur:80,dir:"Use the chart and the two methods. Answer out loud.",desc:"reading reflection, absorption and transmission from data and comparing a digital with an analog signal",html:()=>`<p class="big">A lamp sends 100 units of light at each orchard material. One meter sits behind it and one beside the lamp.</p>
     <table class="bigTable"><tr><th>Material</th><th>Passed through</th><th>Came back</th><th>Neither</th></tr>
     <tr><td>clear plastic film</td><td>88</td><td>9</td><td>3</td></tr>
     <tr><td>white paint on wood</td><td>0</td><td>81</td><td>19</td></tr>
     <tr><td>black plastic mulch</td><td>0</td><td>5</td><td>95</td></tr>
     <tr><td>shade cloth</td><td>68</td><td>20</td><td>12</td></tr>
     <tr><td>apple leaf</td><td>6</td><td>12</td><td>82</td></tr></table>
     <p class="big">Two ways to get the day's bin count to the office 3 km down the lane.<br>Method 1: a needle gauge on a long wire, where the needle's position stands for the count.<br>Method 2: a keypad that sends the count as digits, with one extra check digit at the end.</p>
     <div class="figure">${ico("leaf",74)}${ico("phone",74)}</div>`,qs:["Say what each of white paint, black mulch and clear film mostly does to light, and give the number that shows it.","The apple leaf passes only 6 and takes up 82. Say what the leaf does with the light it takes up, and why a grower would care about the 12 that comes back.","A loose connection makes the wire's resistance drift. Say which method still delivers the right bin count and why, then name what the check digit adds."],key:["White paint reflects: 81 of 100 came back. Black mulch absorbs: 95 of 100 was neither passed nor returned. Clear film transmits: 88 of 100 went through. Every material does all three to some degree, and the largest number in the row names what it mostly does. Partial: naming what each material mostly does with the figures not quoted is approaching. (MS-PS4)","The leaf uses part of the absorbed light to drive photosynthesis and the rest warms the leaf, which also drives water out through its pores. The 12 that comes back is what the grower sees: reflected light is why the leaf looks green, because the pigments absorb red and blue strongly and send more green back. A canopy that reflects more is absorbing less for growth. Partial: naming photosynthesis as the use for the absorbed light with nothing said about the reflected 12 being why the leaf looks green is approaching. (MS-PS4)","The keypad. It is a digital signal: the count is sent as digits, each digit only has to be told apart from the other nine, so a drifting resistance that changes the exact voltage still leaves every digit readable. The needle gauge is analog, where the needle's position carries the value, so drifting resistance moves the needle and reports a wrong count with no sign that anything is wrong. The check digit is computed from the others, so if a digit does arrive wrong the sum no longer fits and the office knows to ask again. Partial: choosing the keypad with nothing said about why the needle gauge hides its own error, or with no account of what the check digit adds, is approaching. (MS-PS4)"]}]},{id:33,title:"The Late Frost",short:"Design",parts:[{std:["MS-ETS1"],n:3,dur:85,dir:"Read the situation and the chart. Answer out loud.",desc:"defining a design problem with criteria and constraints and evaluating competing designs against them",html:()=>`<p class="big">A frost in April kills open blossom, and one is forecast in two days. The orchard has $900, two days before it arrives, 4 hectares to protect, and no budget for new wiring. Whatever is used must not harm the bees that arrive a week later.</p>
     <table class="bigTable"><tr><th>Design</th><th>Cost for 4 ha</th><th>Set up time</th><th>Blossom saved in a trial frost</th><th>Harms bees</th><th>Needs new wiring</th></tr>
     <tr><td>A: overhead sprinklers on the existing pump</td><td>$820</td><td>14 hours</td><td>94 percent</td><td>no</td><td>no</td></tr>
     <tr><td>B: oil fired orchard heaters</td><td>$700</td><td>6 hours</td><td>81 percent</td><td>no</td><td>no</td></tr>
     <tr><td>C: electric fans on towers</td><td>$2,400</td><td>3 days</td><td>88 percent</td><td>no</td><td>yes</td></tr></table>
     <div class="figure">${ico("cherryBlossom",74)}${ico("thermometer",74)}${ico("snowflake",74)}</div>`,qs:["State this as a design problem, then sort every figure in the chart into criteria or constraints.","Which design is ruled out, and on which constraints? Name all of them.","Choose between the two that remain and defend your choice from the chart. Say what you would test first."],key:["Achieve: keep the open blossom above its killing temperature through one April frost across 4 hectares. Criteria, the measures of success: the share of blossom saved, and doing no harm to the bees that follow. Constraints, the limits on any solution: no more than $900, ready within two days, 4 hectares of coverage, and no new wiring. Blossom saved is the only column in the chart that is a criterion; cost, set up time and wiring are all constraints. Partial: a goal stated with cost or set up time filed as criteria rather than constraints is approaching. (MS-ETS1)","Design C is ruled out three times over: $2,400 breaks the $900 budget, three days breaks the two day window, and it needs new wiring, which was excluded outright. A solution that fails a constraint is out whatever its performance, and C saves less blossom than A anyway. Partial: naming Design C with one or two of the three constraints it breaks is approaching. (MS-ETS1)","Either, defended from the chart. A is the stronger answer: it saves 94 percent against 81 percent, it fits the $900 budget at $820, and 14 hours fits inside two days. B is cheaper and far quicker to set up, which matters if the forecast moves earlier, and it leaves $200 unspent. The thing to test first for A is whether the existing pump can actually deliver water to all 4 hectares at once, since the whole plan rests on that and the chart does not say. Partial: a design chosen and defended from the chart with nothing named that would be tested first is approaching. (MS-ETS1)"]},{std:["MS-ETS1"],n:3,dur:85,dir:"Look at the test results. Answer out loud.",desc:"analyzing test data to find which change helps and planning the next round of testing",html:()=>`<p class="big">Four sprinkler settings were tried on one block during a trial frost that reached minus 3 degrees Celsius.</p>
     <table class="bigTable"><tr><th>Version</th><th>Water per hour</th><th>Nozzle spacing</th><th>Switched on at</th><th>Blossom saved</th></tr>
     <tr><td>1</td><td>2 mm</td><td>12 m</td><td>minus 1 degree</td><td>58 percent</td></tr>
     <tr><td>2</td><td>2 mm</td><td>12 m</td><td>plus 1 degree</td><td>86 percent</td></tr>
     <tr><td>3</td><td>2 mm</td><td>8 m</td><td>plus 1 degree</td><td>94 percent</td></tr>
     <tr><td>4</td><td>4 mm</td><td>12 m</td><td>plus 1 degree</td><td>88 percent</td></tr></table>
     <div class="figure">${ico("drop",74)}${ico("wateringCan",74)}</div>`,qs:["Name the one change between versions 1 and 2 and the one change between 2 and 3, and the gain from each.","Version 4 doubled the water. Compare that gain with the gain from closer nozzles, and say which to spend on.","Write version 5 and predict its result, then name a variable the chart has not yet tested and say how you would test it."],key:["Versions 1 to 2: only the switch on temperature changed, from minus 1 degree to plus 1 degree, and the saving rose from 58 to 86 percent, a gain of 28 points. Versions 2 to 3: only the nozzle spacing changed, from 12 m to 8 m, and the saving rose from 86 to 94 percent, a gain of 8 points. Each test changed one variable, which is the only reason a gain can be assigned to a cause. Partial: naming both changes with the 28 point and 8 point gains not worked out is approaching. (MS-ETS1)","Doubling the water from 2 mm to 4 mm an hour added 2 points, 86 to 88 percent. Closing the nozzle spacing from 12 m to 8 m added 8 points, 86 to 94 percent. Closer nozzles gave four times the gain for no extra water, so spend on nozzles. Doubling the water is the weakest of the three changes tested and the most expensive to run. Partial: comparing the 2 points with the 8 points and drawing no spending conclusion is approaching. (MS-ETS1)","Any version argued from the chart. The strongest keeps water at 2 mm an hour, sets nozzles at 8 m, and switches on at plus 1 degree or earlier, since that combines the two changes that worked and avoids the one that did not; predict better than 94 percent and watch whether the gain flattens. The untested variable is switching on earlier still, at plus 2 or plus 3 degrees, so the next test should hold water and spacing at the version 3 settings and vary only the switch on temperature to find where the gain stops. Partial: a version 5 argued from the chart with no untested variable named and no test for it described is approaching. (MS-ETS1)"]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Thorough Evidence",std:["RL.9-10.1"],needs:["RL.8.1"],n:1,dir:"Answer out loud. Read me the exact words.",html:()=>`<p class="big">Lucia does not give up easily. Prove it with strong and thorough evidence: give at least three details from different parts of the story, and explain what each one shows.</p>${story()}`,key:["Three or more details from across the story, each explained. Examples: she offers a plan when he says the tree comes down (“What if we graft it?”); she answers his warning about the wait (“I’m thirteen. I’ve got four years.”); she makes the cut even though her “hands were not steady”; she asks “Now what?” because she is ready for the next step. (HS RL.9-10.1, strong and thorough evidence)"]},2:{id:"L2",title:"Level Up: Mix and Match",std:["N-RN.3"],needs:["8.NS.A.1"],n:3,dir:"Answer out loud. Explain your thinking.",html:()=>`<ol class="qlist"><li>Add ${fr(1,2)} + ${fr(3,4)}. Is the sum rational? Will the sum of two rational numbers always be rational? Explain.</li><li>Is 5 + √3 rational or irrational? Explain how you know.</li><li>Is 4 × √2 rational or irrational? Explain how you know.</li></ol>`,key:["5/4, which is rational. Yes, always: adding two fractions of integers gives another fraction of integers. (HS N-RN.3)","Irrational. If 5 + √3 were a rational number, then subtracting 5 would leave a rational number too, but √3 is irrational. Accept: its decimal never ends or repeats, so adding 5 does not change that. (HS N-RN.3)","Irrational. If 4 × √2 were rational, dividing by 4 would make √2 rational, and it is not. Accept: a nonzero rational number times an irrational number is irrational. (HS N-RN.3)"]},3:{id:"L3",title:"Level Up: Two Moves",std:["G-CO.5"],needs:["8.G.A.3"],n:1,dir:"Answer out loud.",html:()=>`<p class="big">The crew moved the tree block. Triangle JKL landed on J″(−2, −6), K″(−6, −6), L″(−4, −2). Describe a sequence of two transformations that carries triangle JKL onto the new triangle.</p><div class="figure">${twoMoveGrid()}</div>`,key:["Reflect across the y-axis, then translate 8 units down. Check: J(2, 2) → (−2, 2) → (−2, −6). The two moves can be done in either order. Accept any other sequence that lands all three corners correctly. (HS G-CO.5)"]}};const READ_STD=["RL.8.1","RL.8.3","RL.8.4","RI.8.1","RI.8.8","RI.8.9","RL.9-10.1"];const WRITE_STD=["W.8.1","W.8.2","W.8.3"];const MATH_STD=["8.NS.A.1","8.G.A.3","8.EE.A.1","8.EE.A.2","8.EE.B.5","8.EE.C.8","8.F.A.1","8.F.A.3","8.G.B.7","8.SP.A.1","N-RN.3","G-CO.5"];const LOG_NAMES={readq:"Questions read aloud",passage:"Text read aloud by an adult",repeat:"Directions repeated or reworded",vocab:"Word or phrase explained by teacher",hint:"Hint or first step given",fewer:"Fewer questions",time:"Extra time",scribe:"Adult wrote the student’s words",brk:"Break"};function stopLogs(st){const out=["readq"];if(READ_STD.concat(["W.8.8"]).some(x=>st.std.includes(x)))out.push("passage");out.push("repeat","vocab","hint","fewer","time");if(WRITE_STD.concat(["W.8.8"]).some(x=>st.std.includes(x)))out.push("scribe");out.push("brk");return out}const dl=a=>`<dl>${a.map(x=>`<dt>${x[0]}</dt><dd>${x[1]}</dd>`).join("")}</dl>`;const ul=a=>`<ul class="card-list">${a.map(x=>`<li>${x}</li>`).join("")}</ul>`;const G_STORY=[["graft","to join a twig from one tree onto another tree so they grow as one"],["orchard manager","the person who runs the orchard"],["bear fruit","to grow fruit"],["nursery","a business that grows and sells young plants"],["on a slant","at an angle, not straight across"],["tortoise","a slow land turtle"],["hare","an animal like a large, fast rabbit"]];const G_SEED=[["traits","features passed from parent to offspring, such as color or taste"],["pollen","the yellow dust from a flower that helps make seeds"],["genetic","having to do with the traits a living thing gets from its parents"],["variety","one named kind of apple"],["scion","a twig cut from one tree to be joined to another"],["rootstock","the young tree that gives the roots and trunk"],["gene","the part of a cell that controls one trait"]];const G_POEM=[["press","a machine that squeezes juice out of fruit"],["crank","a handle you turn to make a machine work"],["pail","a bucket"],["pulp","the soft, mashed part of fruit left after the juice is out"]];const G_SRC=[["pollinate","to carry pollen from flower to flower so fruit can grow"],["variety","one named kind of apple"],["extension","a university office that shares farm research with the public"],["mason bee","a small wild bee that lives alone, not in a hive"],["guaranteed","promised"]];const G_PLAN=[["bruised","marked or soft from being bumped"],["bargain bin","a box of items sold at a low price"],["press","to squeeze the juice out"]];const G_COLD=[["ripen","to become ready to eat, and later too soft"],["oxygen","a gas in the air that living things take in"],["sealed","closed so tightly that air cannot get in or out"],["controlled atmosphere","air that people have changed on purpose"]];const G_DWARF=[["dwarf rootstock","a rootstock that keeps a grafted tree small"],["standard tree","a full size apple tree"],["trellis","a frame of posts and wire that holds young trees up"],["drip irrigation","pipes that drip water at the base of each tree"],["yield","the amount a tree or a block produces"],["block","one section of an orchard"]];const GLOSS={14:G_DWARF,15:G_DWARF,1:G_STORY,4:G_STORY,5:G_STORY,L1:G_STORY,6:G_SEED,10:G_POEM,11:G_SRC,12:G_PLAN,13:G_COLD};const TERMS=[["cite","point to the exact words in the text that prove your answer"],["strongest evidence","the words that prove the answer best, not just words on the same topic"],["explicit","stated right in the text"],["inference","something the text does not say outright, but that you can figure out from clues"],["dialogue","the words characters say out loud"],["incident","one event in a story"],["reveal","to show something that was hidden"],["figurative language","words that mean something beyond their plain meaning, like a comparison"],["connotation","the feeling a word carries beyond its dictionary meaning"],["tone","the feeling or attitude the words create"],["allusion","a quick reference to a well-known story, person, or event"],["analogy","a comparison that explains one thing by showing how it is like another"]];const FRAMES={cite:["The answer is ____. The words that prove it are “____.”","The strongest evidence is “____” because ____.","I can infer that ____ because the text says “____.”"],"RL.8.3":["When ____ says “____,” it makes ____ decide to ____.","This line shows that ____ is ____ because ____.","Because ____ happened, ____."],"RL.8.4":["The author compares ____ to ____. This shows ____.","The word ____ makes me feel ____.","The tone is “____” because of the words “____.”"],"RI.8.8":["The claim is ____.","The evidence given is ____.","That sentence is not evidence because ____."],"RI.8.9":["The two pieces disagree about ____.","Piece 1 says ____, while Piece 2 says ____.","To decide, I would need ____."]};function framesHtml(st){const k=st.std.includes("RI.8.8")?"RI.8.8":st.std.includes("RI.8.9")?"RI.8.9":st.std.includes("RL.8.3")?"RL.8.3":st.std.includes("RL.8.4")?"RL.8.4":"cite";return`<ul class="starters" style="font-size:1.2rem">${FRAMES[k].map(x=>`<li>${x}</li>`).join("")}</ul>`}function verbsHtml(){return`<h4>Verbals: verb forms doing another job</h4>`+dl([["Gerund","ends in -ing and acts as a noun. <em>Hiking is fun.</em>"],["Participle","often ends in -ing or -ed and describes a noun. <em>The barking dog ran.</em>"],["Infinitive","to + verb. <em>She likes to draw.</em>"]])+`<h4>Voice</h4>`+dl([["Active","the subject does the action. <em>Ray kicked the ball.</em>"],["Passive","the subject receives the action. <em>The ball was kicked by Ray.</em>"]])+`<h4>Mood</h4>`+dl([["Indicative","states a fact. <em>It is raining.</em>"],["Imperative","gives a command. <em>Open the window.</em>"],["Interrogative","asks a question. <em>Is it raining?</em>"],["Conditional","tells what would or could happen. <em>I would go if I could.</em>"],["Subjunctive","a wish or something not true. Uses were. <em>If she were taller, she could reach.</em>"]])}function wt(st){return st.std.includes("SL.8.4")?"talk":st.std.includes("W.8.8")?"notes":st.std.includes("W.8.1")?"argument":st.std.includes("W.8.3")?"narrative":"informative"}const PLAN={argument:["My claim","The evidence I will use","The other side's strongest point","Why my claim still holds"],talk:["My claim","Fact 1 from the chart","Fact 2 from the chart","Why these facts prove my claim","My claim again"],informative:["The topic: what I will explain","Step or fact 1","Step or fact 2","Step or fact 3","Conclusion: why it matters"],narrative:["Who, where, and when","The problem","What happened first, next, last","A line of dialogue I will use","How it ended and what it meant"]};function planHtml(st){return`<p class="small">Copy these headings onto your paper. Jot two or three words next to each one before you start.</p><ol class="card-list">${PLAN[wt(st)].map(x=>`<li>${x}</li>`).join("")}</ol>`}const SENT={talk:{s:["The better plan is ____.","The chart shows that ____.","This matters because ____.","Some people might pick the other plan because ____. However, ____.","For these reasons, ____."],w:["because","for example","however","also","as a result","for these reasons"]},argument:{s:["The orchard should ____.","The evidence for this is ____.","Some would say ____.","Even so, ____."],w:["because","however","even so","on the other hand","therefore"]},informative:{s:["Stores can sell crisp apples in spring because ____.","First, ____.","After that, ____.","As a result, ____.","This is called ____.","In the end, ____."],w:["first","after that","because","as a result","for example","in the end"]},narrative:{s:["It was ____ when ____.","At first, ____.","“____,” ____ said.","By the time ____, ____.","Looking back, I realized ____."],w:["at first","meanwhile","suddenly","after that","by the time","finally","looking back"]},notes:{s:["I trust Source ____ more because ____.","In my own words: ____.","Dr. Sato writes, “____.”","Author. “Title.” Publisher, date."],w:["according to","writes","states","explains"]}};function sentHtml(st){const d=SENT[wt(st)];return`<ul class="starters">${d.s.map(x=>`<li>${x}</li>`).join("")}</ul><h4>Linking words</h4><div class="wordbank">${d.w.map(x=>`<span>${x}</span>`).join("")}</div>`}const CHECK={argument:["I stated a claim.","I gave evidence for it.","I named the other side's strongest point.","I said why my claim still holds.","I kept a formal style.","I reread it for mistakes."],informative:["I introduced the topic.","My facts are in an order that makes sense.","I explained the facts in my own sentences.","I used linking words.","I used topic words.","I ended with a conclusion.","I reread it for mistakes."],narrative:["I set the scene.","Events are in an order that makes sense.","I used dialogue.","I used details the reader can see, hear, or feel.","I used time words.","My ending reflects on what happened.","I reread it for mistakes."]};function checkHtml(st){const k=wt(st);return`<ul class="card-list" style="list-style:none;padding-left:0">${CHECK[CHECK[k]?k:"informative"].map(x=>`<li><label style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" style="width:20px;height:20px;margin-top:4px"> ${x}</label></li>`).join("")}</ul>`}let calcE="",calcAns="";function calcEval(){let e=calcE.replace(/\u00D7/g,"*").replace(/\u00F7/g,"/").replace(/\u2212/g,"-");if(!e||!/^[0-9+\-*/().\s]*$/.test(e))return"";try{const o=(e.match(/\(/g)||[]).length-(e.match(/\)/g)||[]).length;if(o>0)e+=")".repeat(o);const v=Function('"use strict";return ('+e+")")();return Number.isFinite(v)?String(+v.toPrecision(10)):"Error"}catch(x){return"Error"}}function calcHtml(){const keys=["7","8","9","÷","⌫","4","5","6","×","(","1","2","3","−",")","0",".","C","+","="];return`<div class="calc-disp" aria-live="polite">${calcE||"0"}${calcAns!==""?`<br><strong>= ${calcAns}</strong>`:""}</div><div class="calc-keys">${keys.map(k=>`<button data-k="${k}" class="${k==="="?"eq":/[0-9.]/.test(k)?"":"op"}">${k}</button>`).join("")}</div><p class="small">Add, subtract, multiply, and divide. To see a fraction as a decimal, divide the top by the bottom.</p>`}function calcBind(b,r){b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{const k=x.dataset.k;if(k==="C"){calcE="";calcAns=""}else if(k==="⌫"){calcE=calcE.slice(0,-1);calcAns=""}else if(k==="="){calcAns=calcEval()}else{if(calcAns!==""&&calcAns!=="Error"&&/^[+\u2212\u00D7\u00F7]/.test(k))calcE=calcAns;else if(calcAns!=="")calcE="";calcAns="";calcE+=k}r()})}const MULT_N=12;let multSel=[0,0];function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function sqHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>n</th>`;for(let n=1;n<=12;n++)h+=`<th>${n}</th>`;h+=`</tr><tr><th>n²</th>`;for(let n=1;n<=12;n++)h+=`<td>${n*n}</td>`;return h+`</tr></table></div><p class="small">n² means n × n. The square root of a number in the bottom row is the whole number above it. A whole number that is not in the bottom row has an irrational square root.</p>`}const rules=rows=>`<table class="meas">${rows.map(r=>`<tr><th>${r[0]}</th></tr><tr><td class="formula">${r[1]}</td></tr>`).join("")}</table>`;const FORM={"8.NS.A.1":["Rational and irrational",ul(["<strong>Rational:</strong> can be written as a fraction of two integers. Its decimal ends or repeats.","<strong>Irrational:</strong> cannot be written as a fraction. Its decimal never ends and never repeats.","<strong>Repeating decimal to fraction:</strong> call it x. If one digit repeats, multiply by 10. If two digits repeat, multiply by 100. Subtract x, then divide."])],"8.EE.A.1":["Integer exponents",ul(["Same base, multiplying: add the exponents. a<sup>m</sup> × a<sup>n</sup> = a<sup>m+n</sup>","Same base, dividing: subtract the exponents.","A negative exponent means one over the power: a<sup>−n</sup> = 1/a<sup>n</sup>","Anything except 0 to the power 0 is 1."])],"8.EE.A.2":["Square and cube roots",ul(["x² = p has two solutions when p is positive: the positive and the negative square root.","x³ = p has one solution.","A square root of a number that is not a perfect square is irrational."])],"8.EE.B.5":["Slope and unit rate",`<p class="formula">y = mx</p>`+ul(["m is the slope and the unit rate: m = y ÷ x.","A steeper line means a bigger unit rate.","A proportional relationship passes through (0, 0)."])],"8.EE.C.8":["Systems of equations",ul(["The solution is the point where the two lines cross.","To solve by substitution, set the two expressions for the same quantity equal.","Check by putting the answer back into both equations."])],"8.F.A.1":["Functions",ul(["A function gives exactly one output for each input.","If one input appears twice with different outputs, it is not a function."])],"8.F.A.3":["Linear functions",`<p class="formula">y = mx + b</p>`+ul(["m is the constant rate of change and b is the value at x = 0.","A rule with x squared, or x in the denominator, is not linear."])],"8.G.B.7":["Pythagorean theorem",`<p class="formula">a² + b² = c²</p>`+ul(["c is the longest side, the one opposite the right angle.","To find a leg, subtract: a² = c² − b²"])],"8.SP.A.1":["Scatter plots",ul(["Positive association: as one goes up, so does the other. Negative: one goes up while the other goes down.","Form: roughly linear, or curved.","An outlier is a point that sits well away from the pattern."])],"8.G.A.3":["Transformation rules",rules([["Translate right a, up b","(x, y) → (x + a, y + b)"],["Reflect across the x-axis","(x, y) → (x, −y)"],["Reflect across the y-axis","(x, y) → (−x, y)"],["Rotate 90° counterclockwise about the origin","(x, y) → (−y, x)"],["Rotate 90° clockwise about the origin","(x, y) → (y, −x)"],["Rotate 180° about the origin","(x, y) → (−x, −y)"],["Dilate by scale factor k from the origin","(x, y) → (kx, ky)"]])+`<p class="small">Left and down are negative moves.</p>`]};function formHtml(st){return st.std.filter(x=>FORM[x]).map(x=>`<h4>${FORM[x][0]}</h4>${FORM[x][1]}`).join("")}const EX={"8.NS.A.1":[["Turn 0.888... into a fraction",["Let x = 0.888...","One digit repeats, so multiply by 10: 10x = 8.888...","Subtract: 10x − x = 8.888... − 0.888..., so 9x = 8","Divide: x = 8/9"]],["Turn 0.1212... into a fraction",["Let x = 0.1212...","Two digits repeat, so multiply by 100: 100x = 12.1212...","Subtract: 99x = 12","Divide and simplify: x = 12/99 = 4/33"]]],"8.G.A.3":[["Move the point (3, 1) four ways",["Translate 2 right and 4 up: add 2 to x and 4 to y. (5, 5)","Reflect across the y-axis: change the sign of x. (−3, 1)","Rotate 180° about the origin: change both signs. (−3, −1)","Dilate by a scale factor of 2: multiply both by 2. (6, 2)"]]]};function exHtml(st){return st.std.filter(x=>EX[x]).map(x=>EX[x].map(e=>`<h4>${e[0]}</h4><ol class="card-list">${e[1].map(s=>`<li>${s}</li>`).join("")}</ol>`).join("")).join("")+`<p class="small">These are different problems from the ones on the stop. Use the same steps.</p>`}let gridPts=[],gridJoin=false;const GS=440,GM=10,GU=(GS-68)/(2*GM);function pgridHtml(){const lines=[];if(gridJoin)for(let i=1;i<gridPts.length;i++)lines.push([gridPts[i-1],gridPts[i]]);return`<div class="blk-row"><button class="chip" data-g="join" aria-pressed="${gridJoin}">Connect the points</button><button class="chip" data-g="undo">Undo</button><button class="chip" data-g="clear">Clear</button></div><div class="figure" data-pg style="cursor:crosshair">${F.coordGrid({max:GM,quad4:true,size:GS,points:gridPts,lines})}</div><p class="small">Click the grid to plot a point. Points: ${gridPts.map(p=>`(${p[0]}, ${p[1]})`).join(", ")||"none yet"}</p>`}function pgridBind(b,r){b.querySelectorAll("[data-g]").forEach(x=>x.onclick=()=>{const g=x.dataset.g;if(g==="join")gridJoin=!gridJoin;if(g==="undo")gridPts.pop();if(g==="clear")gridPts=[];r()});const svg=b.querySelector("[data-pg] svg");if(!svg)return;svg.onclick=e=>{const q=svg.getBoundingClientRect(),vx=(e.clientX-q.left)*GS/q.width,vy=(e.clientY-q.top)*GS/q.height,x=Math.round((vx-34)/GU)-GM,y=Math.round((GS-34-vy)/GU)-GM;if(Math.abs(x)>GM||Math.abs(y)>GM)return;gridPts.push([x,y]);r()}}const TOOLS={gloss:{name:"Word help",std:["RL.8.1","RL.8.3","RL.8.4","RI.8.1","RI.8.8","RI.8.9","W.8.8","SL.8.4","W.8.1","W.8.2","RL.9-10.1"],html:st=>dl(GLOSS[st.id]||G_STORY)},terms:{name:"Reading terms",std:READ_STD,html:()=>dl(TERMS)},frames:{name:"Answer frames",std:READ_STD,html:framesHtml},verbs:{name:"Grammar card",std:["L.8.1"],html:verbsHtml},plan:{name:"Planner",std:["SL.8.4"].concat(WRITE_STD),html:planHtml},sent:{name:"Sentence frames",std:["SL.8.4","W.8.8"].concat(WRITE_STD),html:sentHtml},check:{name:"Writing checklist",std:WRITE_STD,html:checkHtml},calc:{name:"Calculator",std:MATH_STD,html:calcHtml,bind:calcBind},mult:{name:"Multiplication chart",std:MATH_STD,html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const x=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===x&&multSel[1]===k?[0,0]:[x,k];r()})},sq:{name:"Perfect squares chart",std:["8.NS.A.1","N-RN.3"],html:sqHtml},form:{name:"Formula and definition card",std:Object.keys(FORM),html:formHtml},ex:{name:"Worked example",std:Object.keys(EX),html:exHtml},grid:{name:"Coordinate grid",std:["8.G.A.3","G-CO.5"],html:pgridHtml,bind:pgridBind}};const SUP_CAVEATS=[{t:"passage",msg:"If the text was read to the student, this stop shows listening comprehension, not reading."},{t:"terms",std:["RL.8.4","RL.8.3"],msg:"The reading terms card defines words like tone, connotation, and allusion. This stop then shows applying those ideas with a reference."},{t:"frames",msg:"Answer frames give the sentence structure. Rate the evidence and thinking the student supplied."},{t:"verbs",std:["L.8.1"],msg:"The grammar card defines verbals, voice, and mood with examples, so this stop shows using a reference, not recall."},{t:"plan",msg:"The planner supplies the organization, so count the organization check as supported, not independent."},{t:"sent",msg:"Sentence frames supply the linking words and the closing, so count those checks as supported."},{t:"check",msg:"The checklist names what to include. Note that the student used it to revise."},{t:"calc",std:["8.NS.A.1"],msg:"The calculator shows the decimal for a fraction, so count the fraction to decimal questions as supported."},{t:"sq",std:["8.NS.A.1"],msg:"The chart shows which square roots are whole numbers, so count the √49 question and the “between 3 and 4” question as supported."},{t:"form",std:["8.NS.A.1"],msg:"The card gives the definitions and the steps for repeating decimals, so this stop shows applying them with a reference, not recall."},{t:"form",std:["8.G.A.3"],msg:"The card gives the coordinate rule for each move, so this stop shows applying given rules, not describing the effect independently."},{t:"ex",msg:"A worked example models the method. Count the matching questions as supported."},{t:"grid",std:["8.G.A.3"],msg:"If points were plotted on the grid tool, note whether the student found the coordinates by plotting or by using a rule."},{t:"scribe",msg:"If an adult wrote, rate the ideas and organization. Do not rate conventions the adult supplied."},{t:"fewer",msg:"If questions were skipped, change the “of” number in the score to the number the student tried."},{t:"hint",msg:"Note which question got the hint, and count that question as supported."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,logNames:LOG_NAMES,stopLogs}}});
